92		[Serializable]
93		public class SkillState : State<Enemy>
94		{
95			public string skillID;
96	
97			public int requiredDifficultyLevel;
98	
99			public int priorityLevel;
100	
101			public float minActivationRadius;
102	
103			public float maxActivationRadius;
104	
105			public float cooldownTime;
106	
107			public Cooldown cooldownRef;
108	
109			private static SyncedNumVarStat windupMultiStat;
110	
111			private static SyncedNumVarStat exitMultiStat;
112	
113			private static SyncedNumVarStat cooldownMultiStat;
114	
115			public string castingAnimName = string.Empty;
116	
117			public PowerUpEffect powerUpEffect;
118	
119			public Transform powerUpTrans;
120	
121			public bool usePowerUpEffect = true;
122	
123			public bool playPowerUpAudio = true;
124	
125			public bool disablePowerUpEffect;
126	
127			public Color spellCastColor = defaultCastColor;
128	
129			public Vector2 targetVector;
130	
131			public bool useTargetHurtBox = true;
132	
133			public bool requireLineOfSight = true;
134	
135			public bool isLegendary;
136	
137			public float currentDiffValue;
138	
139			public int windupStopwatchID = -1;
140	
141			public float windupTime = -1f;
142	
143			public bool windupComplete;
144	
145			public float exitTime = -1f;
146	
147			public int exitStopwatchID = -1;
148	
149			public bool exitQueued;
150	
151			private bool registered;
152	
153			public bool isChargeSkill;
154	
155			public static SyncedNumVarStat WindupMultiStat
156			{
157				get
158				{
159					if (windupMultiStat == null)
160					{
161						windupMultiStat = new SyncedNumVarStat(1f);
162					}
163					return windupMultiStat;
164				}
165			}
166	
167			public static SyncedNumVarStat ExitMultiStat
168			{
169				get
170				{
171					if (exitMultiStat == null)
172					{
173						exitMultiStat = new SyncedNumVarStat(1f);
174					}
175					return exitMultiStat;
176				}
177			}
178	
179			public static SyncedNumVarStat CooldownMultiStat
180			{
181				get
182				{
183					if (cooldownMultiStat == null)
184					{
185						cooldownMultiStat = new SyncedNumVarStat(1f);
186					}
187					return cooldownMultiStat;
188				}
189			}
190	
191			public virtual float StdWindupTime => Mathf.Lerp(0.5f, 0.35f, currentDiffValue) * WindupMultiStat.CurrentValue;
192	
193			public virtual float StdExitTime => Mathf.Lerp(0.75f, 0.5f, currentDiffValue) * ExitMultiStat.CurrentValue;
194	
195			public virtual bool WindupCheck => windupComplete;
196	
197			public SkillState(string newName, FSM newFSM, Enemy newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
198				: base(newName, newFSM, newEnt)
199			{
200				skillID = newName;
201				requiredDifficultyLevel = newReq;
202				priorityLevel = newPriority;
203				minActivationRadius = newMin;
204				maxActivationRadius = newMax;
205				cooldownTime = Mathf.Max(2f, newCD * CooldownMultiStat.CurrentValue);
206				RegisterSkill(newAuto);
207			}
208	
209			public static void ApplyGlobalMods(NumVarStatMod givenCD = null, NumVarStatMod givenWindup = null, NumVarStatMod givenExit = null, bool givenStatus = true)
210			{
211				if (givenCD != null)
212				{
213					CooldownMultiStat.Modify(givenCD, givenStatus);
214				}
215				if (givenWindup != null)
216				{
217					WindupMultiStat.Modify(givenWindup, givenStatus);
218				}
219				if (ExitMultiStat != null)
220				{
221					ExitMultiStat.Modify(givenExit, givenStatus);
222				}
223			}
224	
225			public void RegisterSkill(bool makeAvailableToAI = true, bool addToCooldowns = true)
226			{
227				if (makeAvailableToAI)
228				{
229					parent.availableEnemySkillsDict[skillID] = this;
230				}
231				else
232				{
233					parent.availableEnemySkillsDict.Remove(skillID);
234				}
235				if (addToCooldowns)
236				{
237					parent.cooldownManager.Add(skillID, cooldownTime);
238					cooldownRef = parent.cooldownManager.cooldowns[skillID];
239				}
240				registered = true;
241			}
242	
243			public void InitChargeSkillSettings(int maxCharges, float cooldownTime)
244			{
245				isChargeSkill = true;
246				cooldownRef.isChargeSkill = true;
247				cooldownRef.chargeCount = maxCharges;
248				cooldownRef.MaxChargeCount = maxCharges;
249				cooldownRef.remainingTimeStopwatchID = -1;
250				cooldownRef.MaxTime = cooldownTime;
251			}
252	
253			public bool BaseSkillIsReady()
254			{
255				if (parent.CurrentDifficulty < requiredDifficultyLevel)
256				{
257					return false;
258				}
259				if (isChargeSkill)
260				{
261					return parent.cooldownManager.cooldowns[skillID].chargeCount > 0;
262				}
263				return parent.cooldownManager.CheckCooldown(skillID);
264			}
265	
266			public virtual bool IsReady()
267			{
268				return BaseSkillIsReady();
269			}
270	
271			public bool Transition(bool checkIsReady = true)
272			{
273				if (fsm.currentStateName.Contains(skillID) || (checkIsReady && !IsReady()))
274				{
275					return false;
276				}
277				fsm.ChangeState(skillID, allowSelfTransition: true);
278				return true;
279			}
280	
281			public virtual void ExitTransition()
282			{
283				parent.HandleExitTransitions();
284			}
285	
286			public void StartCooldown(float overrideValue = -1f)
287			{
288				if (!registered || (cooldownTime <= 0f && overrideValue <= 0f) || parent == null)
289				{
290					return;
291				}
292				if (isChargeSkill)
293				{
294					if (cooldownRef.chargeCount > 0)
295					{
296						cooldownRef.chargeCount--;
297					}
298					parent.StartCoroutine(parent.cooldownManager.StartChargeCounter(skillID));
299				}
300				else
301				{
302					parent.cooldownManager.StartCooldownTimer(skillID, overrideValue);
303				}
304			}
305	
306			public override void OnEnter()
307			{
308				parent.enemySkillUseInProgress = true;
309				StartCooldown();
310				currentDiffValue = parent.DifficultyValue;
311				isLegendary = parent.IsLegendary;
312				UpdateTargetVector();
313				if (parent.closestTargetInfo != null)
314				{
315					parent.FaceTarget(parent.closestTargetInfo.position, parent.animFacingDirections);
316				}
317				if (usePowerUpEffect)
318				{
319					ActivatePowerUpEffect(spellCastColor);
320				}
321				windupComplete = false;
322				exitQueued = false;
323			}
324	
325			public override void Update()
326			{
327				if (!WindupCheck)
328				{
329					if (ChaosStopwatch.Check(windupStopwatchID))
330					{
331						ExecuteSkill();
332					}
333					else
334					{
335						WindupUpdate();
336					}
337				}
338				else if (exitQueued && ChaosStopwatch.Check(exitStopwatchID))
339				{
340					ExitTransition();
341				}
342			}
343	
344			public override void OnExit()
345			{
346				parent.enemySkillUseInProgress = false;
347				if (usePowerUpEffect)
348				{
349					DeactivatePowerUpEffect();
350				}
351			}
352	
353			public virtual void ActivatePowerUpEffect(Color color, Color? color2 = null, bool skipOutline = false)
354			{
355				if (!disablePowerUpEffect)
356				{
357					powerUpEffect = PoolManager.GetPoolItem<PowerUpEffect>();
358					if (parent.spriteRenderer != null)
359					{
360						powerUpEffect.Activate(parent.spriteRenderer.transform, color);
361					}
362					else
363					{
364						powerUpEffect.Activate(powerUpTrans ?? parent.transform, color);
365					}
366					if (!skipOutline)
367					{
368						parent.SetOutlineColor(color, color2);
369					}
370					if (playPowerUpAudio)
371					{
372						SoundManager.PlayAudioWithDistance("EnemyCast", parent.transform.position);
373					}
374				}
375			}
376	
377			public virtual void DeactivatePowerUpEffect(bool skipBreakEffect = false)
378			{
379				if (powerUpEffect != null)
380				{
381					powerUpEffect.Deactivate();
382				}
383				if (!disablePowerUpEffect)
384				{
385					if (!skipBreakEffect && parent.spriteRenderer.material.GetColor("_OutlineColor") == armorCastColor && !parent.currentStateName.Contains("Dead"))
386					{
387						PoolManager.GetPoolItem<ParticleEffect>("ArmorDissipateEffect").Emit(15, parent.transform.position);
388					}
389					parent.SetOutlineColor(Color.clear, Color.clear);
390				}
391			}
392	
393			public virtual Vector2 UpdateTargetVector(bool updateInfo = false, bool useTransform = false)
394			{
395				if (updateInfo)
396				{
397					parent.UpdateTargetInfo();
398				}
399				if (parent.closestTargetInfo == null || (useTransform && (parent.closestTargetInfo.transform == null || parent.closestTargetInfo.hurtBoxTransform == null)))
400				{
401					targetVector = Vector2.zero;
402				}
403				else
404				{
405					ref Vector2 reference = ref targetVector;
406					Vector3 vector;
407					if (useTargetHurtBox)
408					{
409						vector = ((!useTransform) ? parent.closestTargetInfo.hurtBoxPosition : parent.closestTargetInfo.hurtBoxTransform.position);
410					}
411					else
412					{
413						vector = ((!useTransform) ? parent.closestTargetInfo.position : parent.closestTargetInfo.transform.position);
414					}
415					reference = vector;
416					targetVector = ((!useTargetHurtBox) ? (targetVector - (Vector2)parent.transform.position) : (targetVector - (Vector2)parent.hurtBoxTransform.position)).normalized;
417				}
418				return targetVector;
419			}
420	
421			public virtual void WindupUpdate()
422			{
423			}
424	
425			public virtual void ExecuteSkill()
426			{
427				windupComplete = true;
428				exitStopwatchID = ChaosStopwatch.Begin((!(exitTime >= 0f)) ? StdExitTime : exitTime);
429				exitQueued = true;
430			}
431	
432			public virtual T ChaosInst<T>(GameObject givenPrefab, Vector2? givenPosition = null, Quaternion? givenQuaternion = null, Transform parentTransform = null)
433			{
434				return Globals.ChaosInst<T>(givenPrefab, parentTransform ?? parent.transform.parent, (!givenPosition.HasValue) ? ((Vector2)parent.transform.position) : givenPosition.Value, (!givenQuaternion.HasValue) ? Quaternion.identity : givenQuaternion.Value);
435			}
436		}
