438		public class DashState : SkillState
439		{
440			public bool dashRandom;
441	
442			public bool dashAway;
443	
444			public float dashSpeed;
445	
446			public float dashDuration;
447	
448			public float dashRange;
449	
450			public bool dashOverPits;
451	
452			public bool onlyDashOverPits;
453	
454			public float randomOffSet;
455	
456			public bool disableFloorContact;
457	
458			public bool playDashEffects;
459	
460			public bool isDashing;
461	
462			public Vector2 dashVector;
463	
464			public Vector2 destinationPosition;
465	
466			public bool destinationIsSafe;
467	
468			public float distanceTodestination;
469	
470			public bool allowReset;
471	
472			public bool trackTarget = true;
473	
474			public bool getRandomNearby = true;
475	
476			public NumVarStatMod dashSpeedMod;
477	
478			public NumVarStatMod dashDurationMod;
479	
480			public BoolVarStatMod airborneStatMod;
481	
482			public DashState(string newName, FSM newFSM, Enemy newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
483				: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
484			{
485				if (newReq <= parent.CurrentDifficulty)
486				{
487					parent.lineOfSightLayerMask = ChaosCollisions.layerAllWallAndObst;
488				}
489				playPowerUpAudio = false;
490				dashOverPits = false;
491				onlyDashOverPits = false;
492				dashRandom = false;
493				dashAway = false;
494				dashSpeed = 30f;
495				dashRange = 6f;
496				randomOffSet = 0f;
497				disableFloorContact = true;
498				playDashEffects = true;
499				dashSpeedMod = new NumVarStatMod("dashOverride", dashSpeed, 10, VarStatModType.OverrideWithMods);
500				dashDurationMod = new NumVarStatMod("dashOverride", dashDuration, 10, VarStatModType.OverrideWithMods);
501				airborneStatMod = new BoolVarStatMod(skillID, newModValue: true, 5);
502			}
503	
504			public override bool IsReady()
505			{
506				if (!base.IsReady())
507				{
508					return false;
509				}
510				if (!parent.CanMove || parent.closestTargetInfo == null)
511				{
512					StartCooldown(1f);
513					return false;
514				}
515				dashVector = GetDashVector(parent.closestTargetInfo.position);
516				destinationPosition = GetDestinationVector(parent.transform.position, parent.closestTargetInfo.position);
517				destinationIsSafe = destinationPosition != Vector2.zero && Globals.CheckCircle(destinationPosition, 0.25f, ChaosCollisions.layerPit);
518				if (!destinationIsSafe)
519				{
520					StartCooldown(1f);
521					return false;
522				}
523				if (dashOverPits && allowReset && !Entity.HasLineOfSight(parent.transform.position, parent.closestTargetInfo.position, 1.5f, ChaosCollisions.layerPit, adjustToRange: true))
524				{
525					return true;
526				}
527				if (onlyDashOverPits)
528				{
529					StartCooldown(0.5f);
530					return false;
531				}
532				return true;
533			}
534	
535			public virtual Vector2 GetRandomVector()
536			{
537				return UnityEngine.Random.insideUnitCircle * randomOffSet;
538			}
539	
540			public virtual Vector2 GetDashVector(Vector2 givenTargetLoc)
541			{
542				if (dashRandom)
543				{
544					dashAway = Globals.RandBool;
545				}
546				return ((givenTargetLoc - (Vector2)parent.transform.position) * ((!dashAway) ? 1 : (-1)) + GetRandomVector()).normalized;
547			}
548	
549			public virtual Vector2 GetDestinationVector(Vector2 givenPosition, Vector2 givenTargetLoc)
550			{
551				return Globals.GetLinecastVector(givenPosition, (dashAway || !trackTarget || !(Vector2.Distance(givenPosition, givenTargetLoc) < dashRange)) ? (givenPosition + dashVector * dashRange) : givenTargetLoc, ChaosCollisions.layerAllWallAndObst) - dashVector * 0.25f;
552			}
553	
554			public override void OnEnter()
555			{
556				base.OnEnter();
557				parent.anim.Play(castingAnimName, -1, 0f);
558				dashVector = (destinationPosition - (Vector2)parent.transform.position).normalized;
559				distanceTodestination = Vector2.Distance(parent.transform.position, destinationPosition);
560				dashDuration = distanceTodestination / dashSpeed;
561				allowReset = dashOverPits;
562				parent.movement.dashVector = dashVector;
563				dashSpeedMod.modValue = dashSpeed;
564				dashDurationMod.modValue = dashDuration;
565				parent.movement.dashSpeedStat.AddMod(dashSpeedMod);
566				parent.movement.dashDurationStat.AddMod(dashDurationMod);
567				parent.movement.dashTimer = dashDuration;
568				parent.airborneStat.AddMod(airborneStatMod);
569				if (playDashEffects)
570				{
571					PlayDashEffects();
572				}
573				isDashing = true;
574				parent.ToggleFloorContact(!disableFloorContact);
575				parent.TogglePreventFallCollider(status: false);
576			}
577	
578			public override void Update()
579			{
580				if (!isDashing && ChaosStopwatch.Check(exitStopwatchID))
581				{
582					ExitTransition();
583				}
584			}
585	
586			public override void FixedUpdate()
587			{
588				if (isDashing)
589				{
590					isDashing = IsDashing();
591				}
592			}
593	
594			public override void OnExit()
595			{
596				base.OnExit();
597				parent.movement.dashSpeedStat.RemoveMod(dashSpeedMod.ID);
598				parent.movement.dashDurationStat.RemoveMod(dashDurationMod.ID);
599				parent.movement.EndMovement();
600				parent.ToggleFloorContact();
601				parent.airborneStat.RemoveMod(airborneStatMod);
602				parent.TogglePreventFallCollider(status: true);
603			}
604	
605			public virtual bool IsDashing()
606			{
607				if (!parent.movement.DashToTarget() && (dashSpeed * dashSpeed > Fall.minSqrVelocityToNotFall || Entity.HasLineOfSight(parent.transform.position, parent.transform.position + (Vector3)(dashVector * 2f), 5f, ChaosCollisions.layerAll)))
608				{
609					return true;
610				}
611				exitStopwatchID = ChaosStopwatch.Begin(exitTime);
612				return false;
613			}
614	
615			public virtual void PlayDashEffects()
616			{
617				string audioID = "StandardDash";
618				Vector2? soundOrigin = parent.transform.position;
