	public class FallState : State<Entity>
	{
		protected float fallDuration;

		protected int fallStopwatchID;

		protected int fallDelayStopwatchID;

		private Vector3 targetRotation;

		private Vector3 originalPos;

		private Vector3 targetPos;

		private Vector3 fallScale = new Vector3(0.75f, 0.75f, 1f);

		public bool finishedFalling;

		protected float lerpPercentage;

		protected bool lerpRotation;

		protected bool lerpScale;

		protected bool lerpPosition;

		private bool finishedDelay;

		private float fallDelayTime = 0.1f;

		private string[] ogSortingLayers;

		private SpriteRenderer[] spriteRenderers;

		private bool sortingLayerChanged;

		private float sortingLayerChangePercentage = 0.5f;

		private List<Collider2D> alteredColliders;

		public FallState(string stateName, FSM parentFSM, Entity parentEntity)
			: base(stateName, parentFSM, parentEntity)
		{
			fallDuration = 0.3f;
			fallDelayTime = 0.05f;
			lerpRotation = false;
			lerpScale = true;
			lerpPosition = true;
			alteredColliders = new List<Collider2D>();
			spriteRenderers = parent.GetComponentsInChildren<SpriteRenderer>();
			ogSortingLayers = new string[spriteRenderers.Length];
			for (int i = 0; i < spriteRenderers.Length; i++)
			{
				ogSortingLayers[i] = spriteRenderers[i].sortingLayerName;
			}
		}

		public override void OnEnter()
		{
			SoundManager.PlayAudioWithDistance("Fall", parent.transform.position);
			sortingLayerChanged = false;
			finishedFalling = false;
			finishedDelay = false;
			fallDelayStopwatchID = ChaosStopwatch.Begin(fallDelayTime);
			targetRotation = parent.originalRotation + new Vector3(0f, 0f, 360f);
			originalPos = ((!(parent.spriteRenderer == null)) ? parent.spriteRenderer.transform.localPosition : parent.transform.position);
			targetPos = originalPos + Vector3.down * 3f;
			if (parent.movement != null)
			{
				parent.movement.EndMovement();
			}
			alteredColliders.Clear();
			Collider2D[] componentsInChildren = parent.gameObject.GetComponentsInChildren<Collider2D>();
			foreach (Collider2D collider2D in componentsInChildren)
			{
				if (collider2D.enabled)
				{
					collider2D.enabled = false;
					alteredColliders.Add(collider2D);
				}
			}
			int num = 0;
			int num2 = 0;
			if (worldTileGrid != null)
			{
				for (int j = 1; j < 4 && worldTileGrid.IsValidTile(parent.lastTileRow - j, parent.lastTileCol) && worldTileGrid[parent.lastTileRow - j, parent.lastTileCol].terrain == Tile.TerrainType.Pit; j++)
				{
					num++;
				}
				for (int k = 1; k < 4 && worldTileGrid.IsValidTile(parent.lastTileRow + k, parent.lastTileCol) && worldTileGrid[parent.lastTileRow + k, parent.lastTileCol].terrain == Tile.TerrainType.Pit; k++)
				{
					num2++;
				}
			}
			if (num == 0 && num2 <= 1)
			{
				sortingLayerChangePercentage = 0.4f;
			}
			else if (num2 == 0)
			{
				sortingLayerChangePercentage = 0f;
			}
			else
			{
				sortingLayerChangePercentage = 0.5f;
			}
			parent.TogglePreventFallCollider(status: false);
		}

		public override void Update()
		{
			if (!finishedDelay)
			{
				if (!ChaosStopwatch.Check(fallDelayStopwatchID))
				{
					return;
				}
				finishedDelay = true;
				fallStopwatchID = ChaosStopwatch.Begin(fallDuration);
			}
			if (ChaosStopwatch.Check(fallStopwatchID))
			{
				finishedFalling = true;
				if (lerpScale)
				{
					parent.transform.localScale = Vector3.zero;
				}
				if (lerpRotation)
				{
					parent.transform.eulerAngles = Vector3.zero;
				}
				return;
			}
			lerpPercentage = ChaosStopwatch.GetTimePercentage(fallStopwatchID);
			if (!sortingLayerChanged && lerpPercentage >= sortingLayerChangePercentage)
			{
				sortingLayerChanged = true;
				for (int i = 0; i < spriteRenderers.Length; i++)
				{
					if (spriteRenderers[i] != null)
					{
						spriteRenderers[i].sortingLayerName = "SubFloor";
					}
				}
			}
			if (lerpScale)
			{
				parent.transform.localScale = Vector3.Lerp(parent.originalScale, fallScale, lerpPercentage);
			}
			if (lerpRotation)
			{
				parent.transform.eulerAngles = Vector3.Lerp(parent.originalRotation, targetRotation, lerpPercentage);
			}
			if (lerpPosition && parent.spriteRenderer != null)
			{
				parent.spriteRenderer.transform.localPosition = Vector3.Lerp(originalPos, targetPos, lerpPercentage);
			}
		}

		public override void OnExit()
		{
			parent.transform.localScale = parent.originalScale;
			parent.transform.eulerAngles = parent.originalRotation;
			if (parent.spriteRenderer != null)
			{
				parent.spriteRenderer.transform.localPosition = originalPos;
			}
			foreach (Collider2D alteredCollider in alteredColliders)
			{
				if (alteredCollider != null)
				{
					alteredCollider.enabled = true;
				}
			}
			for (int i = 0; i < spriteRenderers.Length; i++)
			{
				spriteRenderers[i].sortingLayerName = ogSortingLayers[i];
			}
			parent.TogglePreventFallCollider(status: true);
		}
	}

