	public static bool HasLineOfSight(Vector2 position, Vector2 targetPosition, float maxRange, int layerMask, bool adjustToRange = false)
	{
		if (Vector2.Distance(position, targetPosition) > maxRange)
		{
			if (!adjustToRange)
			{
				return false;
			}
			targetPosition = (targetPosition - position).normalized * maxRange + position;
		}
		return Physics2D.LinecastNonAlloc(position, targetPosition, losResults, layerMask) <= 0;
	}

	private static bool TargetInRange(Vector3 position, Vector3 targetPosition, float range, bool requireLOS = false, int LOSLayerMask = 0)
	{
		return Vector2.Distance(position, targetPosition) <= range && (!requireLOS || HasLineOfSight(position, targetPosition, range, LOSLayerMask));
	}

	public static List<GameObject> GetAllTargetsInRange(List<GameObject> targetList, Vector3 originatorPosition, float range, bool playerTagOnly = false, List<GameObject> excludeList = null, GameObject excludeTarget = null, bool requireLOS = false, int LOSLayerMask = 0)
	{
		List<GameObject> list = new List<GameObject>();
		foreach (GameObject target in targetList)
		{
			if (!(target == null) && !(target == excludeTarget) && (excludeList == null || !excludeList.Contains(target)) && TargetInRange(originatorPosition, target.transform.position, range, requireLOS, LOSLayerMask) && (!playerTagOnly || target.tag == "Player"))
			{
				list.Add(target);
			}
		}
		if (GameController.pvpOn && targetList != GameController.allies)
		{
			targetList = GameController.allies;
			foreach (GameObject target2 in targetList)
			{
				if (!(target2 == null) && !(target2 == excludeTarget) && (excludeList == null || !excludeList.Contains(target2)) && TargetInRange(originatorPosition, target2.transform.position, range, requireLOS, LOSLayerMask) && (!playerTagOnly || target2.tag == "Player"))
				{
					list.Add(target2);
				}
			}
		}
		return list;
	}

	public static TargetInfo GetClosestTarget(List<GameObject> targetList, Vector3 originatorPosition, float range, bool playerTagOnly = false, List<GameObject> excludeList = null, GameObject excludeTarget = null, bool requireLOS = false, int LOSLayerMask = 0)
	{
		if (targetList == null)
		{
			return null;
		}
		float num = 9999f;
		float num2 = 0f;
		GameObject gameObject = null;
		foreach (GameObject target in targetList)
		{
			if (!(target == null) && !(target == excludeTarget) && (excludeList == null || !excludeList.Contains(target)))
			{
				num2 = Vector2.Distance(target.transform.position, originatorPosition);
				if (num2 < num && num2 <= range && (!requireLOS || HasLineOfSight(originatorPosition, target.transform.position, range, LOSLayerMask)) && (!playerTagOnly || target.tag == "Player"))
				{
					num = num2;
					gameObject = target;
				}
			}
		}
		if (GameController.pvpOn && targetList != GameController.allies)
		{
			targetList = GameController.allies;
			foreach (GameObject target2 in targetList)
			{
				if (!(target2 == null) && !(target2 == excludeTarget) && (excludeList == null || !excludeList.Contains(target2)))
				{
					num2 = Vector2.Distance(target2.transform.position, originatorPosition);
					if (num2 < num && num2 <= range && (!requireLOS || HasLineOfSight(originatorPosition, target2.transform.position, range, LOSLayerMask)) && (!playerTagOnly || target2.tag == "Player"))
					{
						num = num2;
						gameObject = target2;
					}
				}
			}
		}
		return (!(gameObject == null)) ? GetTargetInfoFromObject(gameObject, num) : null;
	}

