		}
	}

	public IEnumerator FlashInOutline(Color givenColor, Color? givenColor2 = null)
	{
		ChaosQuickStopwatch fadeInTimer = new ChaosQuickStopwatch(0.08f)
		{
			IsRunning = true
		};
		while (fadeInTimer.IsRunning)
		{
			if (spriteRenderer == null)
			{
				yield break;
			}
			if (fsm != null && fsm.currentStateName.Contains("Dead"))
			{
				spriteRenderer.material.SetColor("_OutlineColor", Color.clear);
				spriteRenderer.material.SetColor("_OutlineColor2", Color.clear);
				yield break;
			}
			spriteRenderer.material.SetColor("_OutlineColor", new Color(1f, 1f, 1f, Mathf.Lerp(0f, 1f, fadeInTimer.TimePercentage + 0.5f)));
			spriteRenderer.material.SetColor("_OutlineColor2", new Color(1f, 1f, 1f, Mathf.Lerp(0f, 0.3f, fadeInTimer.TimePercentage + 0.5f)));
			yield return null;
		}
		if (spriteRenderer != null)
		{
			spriteRenderer.material.SetColor("_OutlineColor", givenColor);
			if (givenColor2.HasValue)
			{
				spriteRenderer.material.SetColor("_OutlineColor2", givenColor2.Value);
			}
		}
	}
