	public class BaseAttackCheckState : State<Enemy>
	{
		public string attackStateName = "AttackExecute";
		public float attackCD;
		public int attackCDStopwatchID;
		public bool queueAttackCD;
		public float attackRadiusOffset;
		public BaseAttackCheckState(string newName, FSM newFSM, Enemy newEnt)
			: base(newName, newFSM, newEnt)
		{
			attackCD = 4f;
			queueAttackCD = false;
		}
		public override void OnEnter()
		{
			parent.anim.Play("Idle");
			parent.movement.EndMovement();
			if (queueAttackCD)
			{
				queueAttackCD = false;
				StartCooldownTimer();
			}
		}
		public override void Update()
		{
			if (parent.UpdateTargetInfo(-1f, reqLOS: true) == null)
			{
				fsm.ChangeState(fsm.defaultStateName);
			}
			else if (!parent.HandleExtraSkills(hasLOS: true, updateTarget: true, updateLOS: true))
			{
				if (parent.closestTargetInfo.distance > parent.attackRadius)
				{
					fsm.ChangeState("Chase");
				}
				else if (ChaosStopwatch.Check(attackCDStopwatchID))
				{
					queueAttackCD = true;
					fsm.ChangeState(attackStateName);
				}
			}
		}
		public virtual void StartCooldownTimer()
		{
			attackCDStopwatchID = ChaosStopwatch.Begin(attackCD * Mathf.Lerp(1f, 0.75f, parent.DifficultyValue));
