	public class BaseSpreadShotState : SkillState
	{
		public GameObject projectilePrefab;
		public List<Projectile> projectileList = new List<Projectile>();
		public int projectileCount;
		public int waveCount;
		public int waveCountdown;
		public float waveTime;
		public int waveStopwatchID;
		public float castTime = -1f;
		public int castStopwatchID;
		public float holdTime = -1f;
		public int holdStopwatchID;
		public int totalPositionCount = 12;
		public int positionCount;
		public float spawnRange;
		public bool attackInitalized;
		public bool projectilesCreated;
		public bool projectilesFired;
		public bool trackTarget = true;
		public bool loopingCastingAnim;
		public float originalMoveSpeed = -1f;
		public BaseSpreadShotState(string newName, FSM newFSM, Enemy newEnt, int newReq = 0, int newPriority = 0, float newMin = 0f, float newMax = 0f, float newCD = 0f, bool newAuto = false)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			projectilePrefab = EnemyFireball.Prefab;
			spawnRange = 1.5f;
			projectileCount = 1;
			waveCount = 1;
			waveTime = 0.2f;
		}
		public virtual bool TargetFound()
		{
			if (parent.UpdateTargetInfo(-1f, reqLOS: true) == null)
			{
				ExitTransition();
				return false;
			}
			parent.FaceTarget(parent.closestTargetInfo.position, parent.animFacingDirections);
			parent.anim.Play(castingAnimName);
			targetVector = UpdateTargetVector();
			return true;
		}
		public override void OnEnter()
		{
			if (TargetFound())
			{
				base.OnEnter();
				parent.movement.EndMovement();
				parent.anim.Play(castingAnimName, -1, 0f);
				if (castTime < 0f)
				{
					castTime = StdWindupTime;
				}
				if (holdTime < 0f)
				{
					holdTime = StdWindupTime * 0.5f;
				}
				waveCountdown = waveCount - 1;
				attackInitalized = false;
			}
		}
		public virtual void InitalizeAttack()
		{
			projectileList.Clear();
			projectilesCreated = false;
			projectilesFired = false;
			castStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, castTime / (float)projectileCount, projectileCount);
			positionCount = totalPositionCount - (int)((float)projectileCount * 0.5f);
		}
		public override void ExecuteSkill()
		{
			if (!attackInitalized)
			{
				if (trackTarget && !TargetFound())
				{
					base.ExecuteSkill();
					return;
				}
				attackInitalized = true;
				InitalizeAttack();
			}
			if (!projectilesCreated)
			{
				parent.anim.Play(castingAnimName, -1, 0f);
				if (CreateAllProjectiles())
				{
					projectilesCreated = true;
					holdStopwatchID = ChaosStopwatch.Begin(holdTime);
				}
				return;
			}
			if (!projectilesFired)
			{
				if (!ChaosStopwatch.Check(holdStopwatchID))
				{
					OnProjectileHold();
					return;
				}
				projectilesFired = true;
				FireAllProjectiles();
				if (!loopingCastingAnim)
				{
					parent.anim.Play(castingAnimName, -1, 1f);
				}
				waveStopwatchID = ChaosStopwatch.Begin(waveTime);
			}
			if (waveCountdown > 0)
			{
				if (ChaosStopwatch.Check(waveStopwatchID))
				{
					waveCountdown--;
					attackInitalized = false;
				}
			}
			else
			{
				base.ExecuteSkill();
			}
		}
		public override void ExitTransition()
		{
			if (fsm.HasState("Reposition"))
			{
				fsm.ChangeState("Reposition");
			}
			else
			{
				base.ExitTransition();
			}
		}
		public override void OnExit()
		{
			base.OnExit();
			if (projectilesFired)
			{
				return;
			}
			foreach (Projectile projectile in projectileList)
			{
				if (projectile != null)
				{
					projectile.ResetProjectile();
				}
			}
		}
		public virtual void OnProjectileHold()
		{
			RefreshAllProjectiles();
			if (!loopingCastingAnim)
			{
				parent.anim.Play(castingAnimName, -1, 0f);
			}
		}
		public virtual void RefreshAllProjectiles()
		{
			foreach (Projectile projectile in projectileList)
			{
				if (projectile != null)
				{
					projectile.RefreshFlightTime();
				}
			}
		}
		public virtual bool CreateAllProjectiles()
		{
			switch (ChaosStopwatch.CheckInterval(castStopwatchID))
			{
			case StopwatchState.Running:
				return false;
			case StopwatchState.Ready:
				projectileList.Add(CreateProjectile(Globals.GetRotatedCircleVector(totalPositionCount, positionCount % totalPositionCount, targetVector)));
				positionCount++;
				return false;
			case StopwatchState.Done:
				return true;
			default:
				return true;
			}
		}
		public virtual Projectile CreateProjectile(Vector2 givenVector)
		{
			Projectile projectile = ChaosInst<Projectile>(projectilePrefab, (Vector2)parent.hurtBoxTransform.position + givenVector * spawnRange, Globals.GetRotationQuaternion(givenVector));
			projectile.parentObject = parent.gameObject;
			projectile.parentEntity = parent;
			projectile.attackBox.SetAttackInfo(parent.skillCategory, skillID);
			projectile.attackBox.knockbackOverwriteVector = givenVector;
			projectile.attackBox.collider.enabled = false;
			projectile.moveVector = givenVector;
			originalMoveSpeed = projectile.moveSpeed;
			projectile.moveSpeed = 0f;
			ExtraCreateSettings(projectile);
			projectile.Show();
			return projectile;
		}
		public virtual void FireAllProjectiles()
		{
			foreach (Projectile projectile in projectileList)
			{
				if (projectile != null)
				{
					FireProjectile(projectile);
				}
			}
			projectileList.Clear();
		}
		public virtual void FireProjectile(Projectile givenProj)
		{
			if (!(givenProj == null))
			{
				givenProj.attackBox.collider.enabled = true;
				givenProj.moveSpeed = originalMoveSpeed;
				ExtraFireSettings(givenProj);
			}
		}
		public virtual void ExtraCreateSettings(Projectile givenProj)
		{
		}
		public virtual void ExtraFireSettings(Projectile givenProj)
		{
		}
	}
