public class GhoulLarge : Enemy
{
	public class GhoulLargeFrozenState : EnemyFrozenState
	{
		public GhoulLargeFrozenState(string newName, FSM newFSM, Enemy newEnt)
			: base(newName, newFSM, newEnt)
		{
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.anim.Play("Idle");
		}
	}
	public class GhoulLargeAttackState : SkillState
	{
		private int attackCountMax = 3;
		private int attackCounter;
		private bool attackStarted;
		private bool attackCompleted;
		private int delayStopwatchID;
		private Vector2 currentPosition;
		public new GhoulLarge parent;
		public GhoulLargeAttackState(string newName, FSM newFSM, GhoulLarge newEnt)
			: base(newName, newFSM, newEnt, 0, 0, 0f, 2.5f, 0f, newAuto: false)
		{
			parent = newEnt;
			useTargetHurtBox = false;
			playPowerUpAudio = false;
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			parent.movement.moveVector = targetVector;
			windupTime = StdWindupTime;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			attackCounter = (int)Mathf.Lerp(2f, 0f, currentDiffValue);
			attackStarted = false;
			exitTime = Mathf.Lerp(1.5f, 1f, currentDiffValue);
			parent.anim.Play("AttackRight" + attackCounter + "Windup", -1, 0f);
			string audioID = "GhoulGrowl";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		}
		public override void WindupUpdate()
		{
			if (parent.anim.GetAnimTime() > 0.55f)
			{
				parent.anim.Play("AttackRight" + attackCounter, -1, 0.55f);
			}
		}
		public override void ExecuteSkill()
		{
			if (!attackStarted)
			{
				attackStarted = true;
				attackCompleted = false;
				parent.anim.Play("AttackRight" + attackCounter, -1, 0.55f);
				currentPosition = parent.transform.position;
				if (Globals.CheckLine(currentPosition, currentPosition + targetVector * maxActivationRadius, ChaosCollisions.layerAllWall))
				{
					parent.movement.MoveToMoveVector(32f);
				}
				return;
			}
			if (!attackCompleted)
			{
				if (parent.anim.AnimPlayed(0.7f))
				{
					attackCompleted = true;
					parent.movement.EndMovement();
					currentPosition = (Vector2)parent.transform.position + targetVector * 0.5f;
					CreateAttack(currentPosition);
					delayStopwatchID = ChaosStopwatch.Begin(windupTime * 0.625f);
					int num = attackCounter;
					if (num == 2)
					{
						string audioID = "RockExplode";
						Vector2? soundOrigin = currentPosition;
						float standardPitchRange = SoundManager.StandardPitchRange;
						SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
					}
					else
					{
						string audioID = "RockFormShort";
						Vector2? soundOrigin = currentPosition;
						float standardPitchRange = SoundManager.StandardPitchRange;
						SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
					}
					attackCounter++;
					if (attackCounter >= attackCountMax)
					{
						DeactivatePowerUpEffect();
					}
				}
				return;
			}
			if (parent.anim.AnimPlayed(0.9f))
			{
				parent.anim.Play("AttackRight" + attackCounter, -1, 0.33f);
			}
			if (ChaosStopwatch.Check(delayStopwatchID))
			{
				if (attackCounter < attackCountMax)
				{
					attackStarted = false;
				}
				else
				{
					base.ExecuteSkill();
				}
			}
		}
		private void CreateAttack(Vector2 givenPosition)
		{
			Attack attack = ChaosInst<Attack>(Attack.CirclePrefab, givenPosition);
			attack.SetAttackInfo(parent.skillCategory, parent.attackSkillID, attackCounter + 1);
			attack.knockbackOverwriteVector = targetVector;
			attack.GetComponent<CircleCollider2D>().radius = 1.75f;
			Object.Destroy(attack.gameObject, 0.1f);
			PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, givenPosition);
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 50;
			Vector3? emitPosition = givenPosition;
