	public class BlobRollState : SkillState
	{
		private float targetAcc = 4f;
		private ChaosQuickStopwatch targetStopwatch = new ChaosQuickStopwatch(0.9f);
		private ChaosQuickStopwatch hitStopwatch = new ChaosQuickStopwatch();
		private Transform targetTrans;
		private Vector2 rollVector;
		private Vector2 calcVector;
		private bool targetHit;
		private bool rollStarted;
		private ChaosQuickStopwatch dustTimer;
		private float dustInterval = 0.08f;
		private AudioSource spinAudio;
		public new BlobRoller parent;
		public BlobRollState(string newName, FSM newFSM, BlobRoller newEnt)
			: base(newName, newFSM, newEnt, 0, 0, 0f, newEnt.alertRadius, 0f, newAuto: false)
		{
			parent = newEnt;
			usePowerUpEffect = false;
			useTargetHurtBox = false;
			dustTimer = new ChaosQuickStopwatch(dustInterval);
		}
		public override void OnEnter()
		{
			targetAcc = Mathf.Lerp(4f, 20f, currentDiffValue);
			targetHit = false;
			Attack attack = parent.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			Attack attack2 = parent.attack;
			attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			base.OnEnter();
			parent.attack.gameObject.SetActive(value: true);
			parent.attack.SetAttackInfo(parent.skillCategory, "NeutralBlobRoll");
			rollVector = targetVector;
			parent.anim.Play("Windup", -1, 0f);
			windupTime = StdWindupTime;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			rollStarted = false;
			dustTimer.IsRunning = true;
			SoundManager.PlayAudioWithDistance("BlobCharge", parent.transform.position);
		}
		public override void Update()
		{
			if (targetTrans != null)
			{
				parent.FaceTarget(targetTrans.position, 2);
			}
			if (!targetHit && !dustTimer.IsRunning)
			{
				DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
				int particleCount = 1;
				float z = Globals.GetRotationVector(-rollVector).z;
				float startSpeed = 5f;
				float startSize = 2.5f;
				Vector3? emitPosition = parent.transform.position;
				poolItem.EmitDirBurst(particleCount, z, startSpeed, startSize, -1f, emitPosition);
				dustTimer.IsRunning = true;
			}
			if (!rollStarted && ChaosStopwatch.Check(windupStopwatchID))
			{
				rollStarted = true;
				parent.anim.Play("Roll", -1, 0f);
			}
			if (targetHit)
			{
				if (!hitStopwatch.IsRunning)
				{
					fsm.ChangeState(fsm.defaultStateName);
				}
			}
			else if (!targetStopwatch.IsRunning)
			{
				targetStopwatch.IsRunning = true;
				if (parent.UpdateTargetInfo() == null)
				{
					fsm.ChangeState(fsm.defaultStateName);
					return;
				}
				targetTrans = parent.closestTargetInfo.transform;
				parent.attackCol.enabled = false;
			}
		}
		public override void FixedUpdate()
		{
			if (rollStarted && !targetHit && !(targetTrans == null))
			{
				if (!parent.attackCol.enabled)
				{
					parent.attackCol.enabled = true;
				}
				calcVector = (targetTrans.position - parent.transform.position).normalized;
				rollVector = (rollVector + calcVector * (targetAcc * Time.fixedDeltaTime)).normalized;
				parent.movement.moveVector = rollVector;
				parent.movement.MoveToMoveVector();
				spinAudio = SoundManager.PlayIfNotPlaying("BlobSpin", spinAudio, parent.transform, useStdPitchOverride: false);
			}
		}
		public override void OnExit()
		{
			base.OnExit();
			parent.attackCol.enabled = false;
			StopSpinAudio();
		}
		public void OnTargetHit(Entity givenEnt)
		{
			if (!targetHit && !(givenEnt == null) && !(givenEnt is Destructible))
			{
				targetHit = true;
				hitStopwatch.IsRunning = true;
				parent.attackCol.enabled = false;
				parent.movement.moveVector = -rollVector * 2f;
				parent.movement.MoveToMoveVector();
				parent.anim.Play("Recoil", -1, 0f);
				StopSpinAudio();
				SoundManager.PlayAudioWithDistance("BlobAttack", parent.transform.position);
			}
		}
		private void StopSpinAudio()
		{
			if (spinAudio != null)
			{
				spinAudio.Stop();
				spinAudio = null;
			}
		}
	}
