		health.ignoreSlow.Modify(Health.baseIgnoreMod, addMod: true);
		health.ignoreFreeze.Modify(Health.baseIgnoreMod, addMod: true);
		health.healthStat.AddMod(new NumVarStatMod("MiniBossHP", 750 + 75 * GameController.CurrentDifficulty, 10, VarStatModType.Override, fillToNewMax: true));
