		if (spriteRenderer.material.HasProperty("_PaletteCount"))
		{
			int num = (int)spriteRenderer.material.GetFloat("_PaletteCount");
			if (num > EnemyElementCount + 1)
			{
				spriteRenderer.material.SetFloat("_PaletteIndex", miniBossPaletteIndex);
				paletteIndex = miniBossPaletteIndex;
			}
		}
		auraEmitter = PoolManager.GetPoolItem<MiniBossAura>("MiniBossAura");
		StartAura();
		SetOutlineColor(status: true);
		if (globalMiniBossSpawnEventHandlers != null)
		{
			globalMiniBossSpawnEventHandlers(this);
		}
	}
	public virtual void StartAura()
	{
		auraEmitter.Play(2f, transform.position, hurtBoxTransform);
	}
	public virtual void AllowHurtState(bool status, bool skipBreakEffect = false, bool skipOutline = false)
	{
		if (!(health == null))
		{
			health.ignoreHurtVarStat.Modify(bossIgnoreMod, !status);
			health.ignoreKnockbackVarStat.Modify(bossIgnoreMod, !status);
			health.flashRedOnHit = status;
			health.faceHurtDirection = status;
			if (!skipOutline)
			{
				SetOutlineColor(!status);
			}
			if (status && !skipBreakEffect && !fsm.currentStateName.Contains("Dead"))
			{
				PoolManager.GetPoolItem<ParticleEffect>("ArmorDissipateEffect").Emit(15, transform.position);
			}
		}
	}
	public virtual void SetOutlineColor(bool status)
	{
		if (armorFlashInCoroutine != null)
		{
			StopCoroutine(armorFlashInCoroutine);
		}
		if (spriteRenderer != null)
		{
			if (status)
			{
				armorFlashInCoroutine = StartCoroutine(FlashInOutline(Enemy.armorCastColor, Enemy.armorCastColor2));
				return;
			}
			spriteRenderer.material.SetColor("_OutlineColor", Color.clear);
			spriteRenderer.material.SetColor("_OutlineColor2", Color.clear);
		}
	}
	private new void OnDestroy()
	{
		if (auraEmitter != null)
		{
			auraEmitter.Stop();
		}
	}
}

