	public class SuperKnightLungeState : LungeState
	{
		private Vector2 targetLocation;
		private Attack lungeAttackBox;
		private Vector2 warningPosition;
		private float warningValue;
		private DustEmitter dustEmitter;
		private Vector2 dustVector;
		private float dustWeight = 0.5f;
		private Vector2 calcVector;
		private bool repeatLunge;
		private bool repeatQueued;
		public new SuperKnight parent;
		public SuperKnightLungeState(string newName, FSM newFSM, SuperKnight newEnt, int newReq, int newPriority, float newMin, float newMax, float newCD, bool newAuto = true)
			: base(newName, newFSM, newEnt, newReq, newPriority, newMin, newMax, newCD, newAuto)
		{
			parent = newEnt;
			usePowerUpEffect = false;
			appendFacingDirectionToAtkAnim = false;
			castingAnimName = "LungeWindup";
			attackAnimName = "Lunge";
			attackSkillID = "SuperKnightLunge";
			attackAnimActiveTime = 0.35f;
			dashSpeed = Mathf.Lerp(45f, 55f, parent.DifficultyValue);
			dashDuration = 0.2f;
			lungeAttackBox = parent.transform.Find("LungeAttackBox").GetComponent<Attack>();
			lungeAttackBox.SetAttackInfo(parent.skillCategory, attackSkillID);
			Attack attack = lungeAttackBox;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnAttackHit));
			lungeAttackBox.gameObject.SetActive(value: false);
			useTargetHurtBox = false;
		}
		public override void OnEnter()
		{
			if (repeatLunge)
			{
				dashDuration = 0.25f;
				windupTime = StdWindupTime * 2f;
				exitTime = StdExitTime * 1.75f;
			}
			else
			{
				dashDuration = 0.2f;
				windupTime = StdWindupTime * 1.5f;
				exitTime = StdExitTime * 1.25f;
			}
			base.OnEnter();
			SoundManager.PlayAudioWithDistance("EnemyCast", parent.transform.position);
			dustEmitter = PoolManager.GetPoolItem<DustEmitter>();
			warningPosition = parent.transform.position;
			warningValue = dashDuration * dashSpeed - 1f;
			for (int i = 0; (float)i < warningValue; i++)
			{
				warningPosition += targetVector;
				if (Globals.CheckCircle(warningPosition, 0.125f, ChaosCollisions.layerAllWallAndObst))
				{
					EmitDustBurst(warningPosition, targetVector, 10, 20f);
				}
			}
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 180;
			float scale = 0.05f;
			Vector3? emitPosition = parent.transform.position;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			repeatQueued = !repeatLunge && currentDiffValue > 0f;
			repeatLunge = repeatQueued;
			parent.AllowHurtState(status: false);
		}
		public override void OnExit()
		{
			base.OnExit();
			lungeAttackBox.gameObject.SetActive(value: false);
		}
		public override void ExitTransition()
		{
			base.ExitTransition();
			parent.AllowHurtState(status: false);
		}
		public override void ExecuteSkill()
		{
			if (!lungeStarted)
			{
				lungeAttackBox.gameObject.SetActive(value: true);
				lungeAttackBox.transform.localEulerAngles = -new Vector3(0f, 0f, Vector3.Angle(Vector3.up, targetVector));
				EmitDustBurst(parent.transform.position, -targetVector, 20, 30f);
			}
			base.ExecuteSkill();
		}
		public override void OnLungeComplete()
		{
			base.OnLungeComplete();
			lungeAttackBox.gameObject.SetActive(value: false);
			parent.movement.EndMovement();
			CameraController.ShakeCamera();
			EmitDustBurst(parent.transform.position, targetVector, 50, 50f);
			string audioID = "GroundSlam";
			Vector2? soundOrigin = parent.transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
			if (repeatLunge && parent.UpdateTargetInfo() != null && Vector2.Distance(parent.transform.position, parent.closestTargetInfo.position) < maxActivationRadius * 1.25f)
			{
				fsm.ChangeState(name, allowSelfTransition: true);
				return;
			}
			repeatLunge = false;
			parent.movement.moveVector = targetVector;
			parent.movement.MoveToMoveVector(10f);
			parent.AllowHurtState(status: true);
		}
		private void EmitDustBurst(Vector2 givenPosition, Vector2 givenVector, int givenCount, float givenSpeed)
		{
			givenPosition -= givenVector * 0.5f;
			dustVector = Globals.GetPerpendicular(givenVector) * dustWeight;
			DustEmitter dustEmitter = this.dustEmitter;
			int particleCount = givenCount;
			float z = Globals.GetRotationVector(givenVector).z;
			float startSpeed = givenSpeed;
			float startSize = 2.5f;
			Vector3? emitPosition = givenPosition - givenVector * 0.5f;
			dustEmitter.EmitDirBurst(particleCount, z, startSpeed, startSize, -1f, emitPosition);
			calcVector = (givenVector + dustVector).normalized;
			DustEmitter dustEmitter2 = this.dustEmitter;
			particleCount = givenCount;
			startSize = Globals.GetRotationVector(calcVector).z;
			startSpeed = givenSpeed;
			z = 2.5f;
			emitPosition = givenPosition - calcVector;
			dustEmitter2.EmitDirBurst(particleCount, startSize, startSpeed, z, -1f, emitPosition);
			calcVector = (givenVector - dustVector).normalized;
			DustEmitter dustEmitter3 = this.dustEmitter;
			particleCount = givenCount;
			z = Globals.GetRotationVector(calcVector).z;
			startSpeed = givenSpeed;
			startSize = 2.5f;
			emitPosition = givenPosition - calcVector;
			dustEmitter3.EmitDirBurst(particleCount, z, startSpeed, startSize, -1f, emitPosition);
		}
		private void OnAttackHit(Entity givenEntity)
		{
			if (!(givenEntity == null) && !(givenEntity is Destructible))
			{
				repeatLunge = false;
			}
		}
	}
