using Chaos.AnimatorExtensions;
using UnityEngine;
public class Coffin : Enemy
{
	public class CoffinAttackState(string newName, FSM newFSM, Coffin newEnt) : State<Coffin>(newName, newFSM, newEnt)
	{
		private float jumpRange = 7f;
		private bool isJumping;
		private bool targetLocked;
		private bool moveCompleted;
		private Vector2 currentPosition;
		private Vector2 targetPosition;
		private CastingCircle castingCircle;
		public override void OnEnter()
		{
			if (!parent.MovementEnabled)
			{
				fsm.ChangeState(fsm.defaultStateName);
				return;
			}
			targetPosition = parent.closestTargetInfo.position;
			parent.FaceTarget(targetPosition, parent.animFacingDirections);
			parent.anim.PlayDirectional("AttackDown");
			parent.movement.EndMovement();
			isJumping = false;
			targetLocked = false;
			moveCompleted = false;
			parent.attack.SetAttackInfo(parent.skillCategory, parent.attackSkillID);
			string animName = "Spin";
			Vector3 position = parent.transform.position;
			GameObject gameObject = parent.gameObject;
			Color? color = CastingCircle.enemyColor;
			castingCircle = CastingCirclePool.Spawn(animName, position, disableWithParentVal: true, gameObject, trackParentVal: true, useCastTimeVal: false, 0f, 1.25f, 1.25f, color);
		}
		public override void Update()
		{
			if (parent.anim.AnimPlayed(1.25f))
			{
				parent.HandleExitTransitions();
				return;
			}
			if (isJumping != parent.isJumping)
			{
				isJumping = parent.isJumping;
				if (isJumping)
				{
					parent.spriteSorter.sortingLayer = "OverlayDoodad";
					parent.spriteRenderer.sortingLayerName = "OverlayDoodad";
					if (!targetLocked)
					{
						targetLocked = true;
						if (parent.UpdateTargetInfo() != null && parent.HasTargetInfoLOS())
						{
							currentPosition = parent.transform.position;
							targetPosition = parent.closestTargetInfo.position;
							if (Vector2.Distance(currentPosition, targetPosition) > jumpRange)
							{
								targetPosition = currentPosition + jumpRange * (targetPosition - currentPosition).normalized;
							}
							targetPosition = Globals.GetLinecastVector(currentPosition, targetPosition, ChaosCollisions.layerAllWallAndObst);
							parent.FaceTarget(targetPosition, parent.animFacingDirections);
						}
					}
				}
				else
				{
					parent.spriteSorter.sortingLayer = "Actor";
					parent.spriteRenderer.sortingLayerName = "Actor";
					if (targetLocked)
					{
						parent.movement.EndMovement();
						ResetCastingCircle();
					}
				}
			}
			if (!moveCompleted && isJumping)
			{
				moveCompleted = parent.movement.MoveToTarget(targetPosition, 0.25f);
			}
		}
		public override void OnExit()
		{
			ResetCastingCircle();
		}
		private void ResetCastingCircle()
		{
			if (castingCircle != null)
			{
				castingCircle.Reset();
				castingCircle = null;
			}
		}
	}
	private bool isJumping;
	private Transform targetCircle;
	private SortSpriteLayer spriteSorter;
	private BoolVarStatMod isJumpingMod = new BoolVarStatMod("CoffinJump", newModValue: true);
	public override void InitComponents()
	{
		base.InitComponents();
		targetCircle = transform.Find("TargetCircle");
		spriteSorter = GetComponent<SortSpriteLayer>();
	}
	public override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		attackSkillID = "NeutralCoffinAttack";
		fsm.AddState(new IdleState("Idle", fsm, this)
		{
			multiAnimIdle = true
		});
		fsm.AddState(new CoffinAttackState("Attack", fsm, this));
		fsm.AddState(new EnemyDeadState("Dead", fsm, this));
		fsm.AddState(new EnemyFallState("Fall", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}
	public override void InitAudio()
	{
		base.InitAudio();
		minPitch = 0.8f;
		maxPitch = 0.9f;
	}
	public override void Start()
	{
		base.Start();
		lineOfSightLayerMask = ChaosCollisions.layerAllWallAndObst;
		TogglePreventFallCollider(status: false);
	}
	public void ToggleIsJumping(int status = 1)
	{
		isJumping = status == 1;
		airborneStat.Modify(isJumpingMod, isJumping);
	}
	public void Land()
	{
		if (Globals.CheckCircle(transform.position, 0.25f, ChaosCollisions.layerPit))
		{
			CameraController.ShakeCamera();
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 40;
			float scale = 0.5f;
			Vector3? emitPosition = transform.position;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, transform.position);
		}
	}
}
