using UnityEngine;
public class Cyclops : Enemy
{
	public class CyclopsAttackState : SkillState
	{
		private static Dictionary<FacingDirection, Vector3> shootPos;
		private Transform targetTrans;
		private int laserStopwatchID;
		private bool attackAnimPlayed;
		private ParticleEffect chargeEffect;
		private ParticleEffect chargeEffect2;
		private ChaosQuickStopwatch directionStopwatch = new ChaosQuickStopwatch(0.5f);
		private int maxHits = 6;
		public new Cyclops parent;
		public CyclopsAttackState(string newName, FSM newFSM, Cyclops newEnt, float newRange, float newCD)
			: base(newName, newFSM, newEnt, 0, 0, 0f, newRange, newCD)
		{
			parent = newEnt;
			if (shootPos == null)
			{
				shootPos = new Dictionary<FacingDirection, Vector3>
				{
					{
						FacingDirection.Up,
						new Vector3(0f, 1.75f, 0f)
					},
					{
						FacingDirection.Right,
						new Vector3(0.5f, 1.325f, 0f)
					},
					{
						FacingDirection.Down,
						new Vector3(0f, 1.325f, 0f)
					},
					{
						FacingDirection.Left,
						new Vector3(-0.5f, 1.325f, 0f)
					}
				};
			}
		}
		public override void OnEnter()
		{
			if (parent.closestTargetInfo == null)
			{
				targetTrans = null;
				return;
			}
			targetTrans = parent.closestTargetInfo.hurtBoxTransform;
			if (!(targetTrans == null))
			{
				base.OnEnter();
				parent.FaceTarget(targetTrans.position, 4, useHurtBox: true);
				parent.anim.PlayDirectional("Charge" + parent.facingDirection);
				maxHits = Mathf.CeilToInt(Mathf.Lerp(6f, 10f, currentDiffValue));
				parent.currentLaser.chargeTime = StdWindupTime * 1.25f;
				parent.currentLaser.turnSpeed = Mathf.Lerp(28f, 36f, currentDiffValue);
				parent.currentLaser.timeTilMaxRange = Mathf.Lerp(0.5f, 0.375f, currentDiffValue);
				parent.currentLaser.transform.position = parent.transform.position + shootPos[parent.facingDirection];
				parent.SetLaserAttackInfo();
				parent.currentLaser.Activate(targetTrans);
				Attack attack = parent.currentLaser.attack;
				attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnLaserHit));
				Attack attack2 = parent.currentLaser.attack;
				attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnLaserHit));
				laserStopwatchID = ChaosStopwatch.Begin(Mathf.Lerp(1.5f, 2f, currentDiffValue));
				parent.movement.EndMovement();
				attackAnimPlayed = false;
				chargeEffect = PoolManager.GetPoolItem<ParticleEffect>("ChaosChargeEffect");
				chargeEffect.followTransform = parent.transform;
				chargeEffect.followOffset = shootPos[parent.facingDirection];
				ParticleEffect particleEffect = chargeEffect;
				float? emissionRate = 6f;
				ParticleSystemOverride startLifeTime0p = ParticleEffectOverrides.StartLifeTime0p33;
				particleEffect.Play(emissionRate, null, startLifeTime0p);
				chargeEffect2 = PoolManager.GetPoolItem<ParticleEffect>("ChaosBlobChargeEffect");
				chargeEffect2.followTransform = parent.transform;
				chargeEffect2.followOffset = shootPos[parent.facingDirection];
				chargeEffect2.Play(14f);
				SoundManager.PlayAudioWithDistance("ChaosBeamStart", parent.transform.position);
			}
		}
		public override void Update()
		{
			if (targetTrans == null || parent.currentLaser == null || parent.currentLaser.fsm.currentStateName == "Inactive" || ChaosStopwatch.Check(laserStopwatchID))
			{
				fsm.ChangeState(fsm.defaultStateName);
			}
			else if (parent.currentLaser.fsm.currentStateName.Contains("Shoot"))
			{
				if (!attackAnimPlayed)
				{
					attackAnimPlayed = true;
					parent.anim.PlayDirectional("Attack" + parent.facingDirection);
					StopChargeEffects();
					return;
				}
