	public IEnumerator StartLightShow()
	{
		spriteRenderer.material = Globals.SpriteUnlitMaterial;
		spriteRenderer.material.SetFloat("_FlashAmount", 1f);
		lootPosition = spriteRenderer.transform.position + new Vector3(0f, 0.5f, 0f);
		yield return null;
		int beamCount = 3;
		bool initialBeams = true;
		float lerpMod = 1f;
		SoundManager.PlayAudioWithDistance("LightBeamWindup", transform.position, null, 24f, 0.55f);
		while (!anim.AnimPlayed(0.85f))
		{
			if (!initialBeams)
			{
				beamCount = UnityEngine.Random.Range(1, 3);
			}
			else
			{
				initialBeams = false;
			}
			for (int i = 0; i < beamCount; i++)
			{
				AnimEffect poolItem = PoolManager.GetPoolItem<AnimEffect>("LightBeam");
				poolItem.Play(lootPosition, animSpeed: UnityEngine.Random.Range(0.5f, 1.25f), localEulerAngles: new Vector3(0f, 0f, UnityEngine.Random.Range(0f, 360f)), animName: string.Empty, normalizedTime: Uni
			}
			lerpMod = Mathf.Lerp(1f, 0.5f, anim.GetAnimTime());
			yield return new WaitForSeconds(UnityEngine.Random.Range(0.02f, 0.15f) * lerpMod);
		}
	}
	public void PlayRunEffect()
	{
		PoolManager.GetPoolItem<ConfettiEffect>().EmitSingle(2, hurtBoxTransform.position, ConfettiEffect.PinataMinMaxGradient, ConfettiEffect.SmallCircleOverride);
