		{
			allowReset = true,
			dashOverPits = true,
			onlyDashOverPits = true,
			castingAnimName = "Dash"
		});
		fsm.AddState(new FrostKnightGuardState("Guard", fsm, this));
		fsm.AddState(shieldState = new FrostKnightIceShieldState("FrostKnightIceShield", fsm, this, 0, 7, 0f, 10f, 10f));
