		}
		public override void PlayDeadAudio()
		{
			string audioID = "EnemyDead";
			Vector2? soundOrigin = parent.transform.position;
			float overridePitch = Random.Range(1.25f, 1.5f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
		}
	}
	[HideInInspector]
	public Transform atkTrans;
	public bool isStationary;
	private static NumVarStatMod stationaryHealthMod = new NumVarStatMod("ZoneEnemyMod", 25f, 10, VarStatModType.Additive, fillToNewMax: true);
	public override void Awake()
	{
		base.Awake();
		atkTrans = transform.Find("AttackOrigin");
	}
	public override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new ZoneIdleState("Idle", fsm, this));
		fsm.AddState(new ZoneRepositionState("Reposition", fsm, this));
		fsm.AddState(new ZoneHurtState("Hurt", fsm, this));
		fsm.AddState(new ZoneDeadState("Dead", fsm, this));
		fsm.AddState(new EnemyFrozenState("Frozen", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}
	public override void InitAudio()
	{
	}
	public override void Start()
	{
		base.Start();
		if (isStationary)
		{
			health.healthStat.AddMod(stationaryHealthMod);
		}
	}
