using UnityEngine;
public class EarthZoneEnemy : ZoneEnemy
{
	public class EarthZoneAttackState(string newName, FSM newFSM, ZoneEnemy newEnt) : ZoneAttackState(newName, newFSM, newEnt)
	{
		private SpikeWave currentSW;
		private int waveCount = 4;
		private int randOffset;
		private bool audioPlayed;
		private Vector2 currentPosition;
		public override void OnEnter()
		{
			base.OnEnter();
			SoundManager.PlayAudioWithDistance("BlobCharge", parent.transform.position);
			audioPlayed = false;
		}
		public override void ExecuteAttack()
		{
			parent.anim.Play("Attack", -1, 0.5f);
			currentPosition = parent.transform.position;
			LeafEmitter poolItem = PoolManager.GetPoolItem<LeafEmitter>("FallingLeafEmitter");
			int? particleCount = Random.Range(1, 3);
			Vector3? position = currentPosition + Vector2.up * 1.5f;
			ParticleSystemOverride radius0p = ParticleEffectOverrides.Radius0p75;
			poolItem.EmitSingle(particleCount, position, radius0p);
			DustEmitter poolItem2 = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount2 = 20;
			float scale = 0.1f;
			float startSpeed = 4f;
			position = currentPosition;
			poolItem2.EmitCircle(particleCount2, scale, startSpeed, -1f, position);
			CameraController.ShakeCamera(0.25f);
			PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, currentPosition);
			DustEmitter poolItem3 = PoolManager.GetPoolItem<DustEmitter>();
			particleCount2 = 25;
			position = currentPosition;
			poolItem3.EmitCircle(particleCount2, 1f, -1f, -1f, position);
			string audioID = "RockExplode";
			Vector2? soundOrigin = currentPosition;
			startSpeed = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, startSpeed);
			randOffset = (Globals.RandBool ? 1 : 0);
			waveCount = (int)Mathf.Lerp(4f, 6f, parent.DifficultyValue) * 2;
			for (int i = 0; i < waveCount; i += 2)
			{
				CreateEarthWave(Globals.GetCirclePositionVector(waveCount, i + randOffset));
			}
			base.ExecuteAttack();
		}
		private void CreateEarthWave(Vector2 givenVector)
		{
			currentSW = Globals.ChaosInst<SpikeWave>(SpikeWave.Prefab, null, (Vector2)parent.transform.position + givenVector);
			currentSW.SetSkillData(parent.skillCategory, "EarthZoneAttack");
			currentSW.moveVector = givenVector;
			currentSW.playSoundOnce = audioPlayed;
			audioPlayed = true;
		}
	}
