using System;
public class EnemyCountUp : Item
{
	public static string staticID = "EnemyCountUp";
	private NumVarStatMod healthMod;
	protected override string ExtraInfo => PercentToStr(healthMod, "-");
	public EnemyCountUp()
	{
		ID = staticID;
		category = Category.Misc;
		isCursed = true;
		hubOnly = true;
		healthMod = new NumVarStatMod(ID, -0.2f, 10, VarStatModType.Multiplicative);
	}
	public override void Activate()
	{
		SetEventHandlers(givenStatus: true);
	}
	public override void Deactivate()
	{
		SetEventHandlers(givenStatus: false);
	}
	private void SetEventHandlers(bool givenStatus)
	{
		Level.doubleEnemies = givenStatus;
		SetModStatus(givenStatus);
		Enemy.enemySpawnEventHandlers = (Enemy.EnemySpawnEventHandler)Delegate.Remove(Enemy.enemySpawnEventHandlers, new Enemy.EnemySpawnEventHandler(OnEnemySpawn));
		if (givenStatus)
		{
			Enemy.enemySpawnEventHandlers = (Enemy.EnemySpawnEventHandler)Delegate.Combine(Enemy.enemySpawnEventHandlers, new Enemy.EnemySpawnEventHandler(OnEnemySpawn));
		}
	}
	private void OnEnemySpawn(Enemy givenEnemy)
	{
		ApplyHealthModToEntity(givenEnemy, givenStatus: true);
	}
	private void SetModStatus(bool gs)
	{
		for (int i = 0; i < GameController.enemies.Count; i++)
		{
			if (GameController.enemies[i] != null)
			{
				ApplyHealthModToEntity(GameController.enemies[i].GetComponent<Enemy>(), gs);
			}
		}
	}
	private void ApplyHealthModToEntity(Entity givenEntity, bool givenStatus)
	{
		if (givenEntity != null)
		{
			givenEntity.health.healthStat.Modify(healthMod, givenStatus);
		}
	}
}

