using System.Linq;
using UnityEngine;
public class SurvivalRoom : MonoBehaviour
{
	public delegate void OnSurvivalRoomClearEventHandler();
	private static GameObject prefab;
	private static MapDirections[] validWallTypes = new MapDirections[4]
	{
		MapDirections.North,
		MapDirections.South,
		MapDirections.East,
		MapDirections.West
	};
	public static OnSurvivalRoomClearEventHandler onSurvivalRoomClearEventHandlers;
	private static Vector3 northGateOffset = new Vector3(-3f, 0f, 0f);
	private static Vector3 southGateOffset = new Vector3(-3f, -4f, 0f);
	private static Vector3 eastGateOffset = new Vector3(1f, 0f, 0f);
	private static Vector3 westGateOffset = new Vector3(0f, 0f, 0f);
	public EnemyFactory[] enemyFactories;
	private RetractableWall[] retractableWalls;
	public bool roomCleared;
	public bool triggered;
	public bool spawnTreasureChest;
	public string treasureChestLootID = "TreasureChestSmall";
	private Room roomScript;
	private Vector3 roomPos;
	private static GameObject horGatePrefab;
	private static GameObject vertGatePrefab;
	private GameObject northGate;
	private GameObject southGate;
	private GameObject eastGate;
	private GameObject westGate;
	private bool gatesInstantiated;
	private float checkPlayerStatusInterval;
	private int intervalStopwatchID = -1;
	private List<TriggerEvent> triggerEvents;
	private int targetPlayerID;
	private Player targetPlayer;
	public int order;
	private SurvivalRoom[] survivalRooms;
	private HazardRoom hazardRoom;
	[HideInInspector]
	public List<HazardRoom> hazardRoomList;
	private Transform checkpointTrans;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Environment/SurvivalRoom.prefab"));
	private void OnTriggerEnter2D(Collider2D col)
	{
		if (triggered || triggerEvents == null)
		{
			return;
		}
		foreach (TriggerEvent triggerEvent in triggerEvents)
		{
			if (!triggerEvent.CheckCollision(col))
			{
				continue;
			}
			targetPlayer = col.transform.parent.GetComponent<Player>();
			targetPlayerID = targetPlayer.playerID;
			Activate();
			break;
		}
	}
	public void Awake()
	{
		if (order == 0)
		{
			triggerEvents = new List<TriggerEvent>();
			triggerEvents.Add(new TriggerEvent("AllyFloorContact", "Player", string.Empty));
			triggerEvents.Add(new TriggerEvent("IgnoreFloorContact", "Player", string.Empty));
		}
		roomCleared = false;
		gatesInstantiated = false;
		checkPlayerStatusInterval = 1f;
		if (horGatePrefab == null)
		{
			horGatePrefab = ChaosBundle.Get("Assets/Prefabs/Environment/HorGateUnit.prefab");
		}
		if (vertGatePrefab == null)
		{
			vertGatePrefab = ChaosBundle.Get("Assets/Prefabs/Environment/VertGateUnit.prefab");
		}
		hazardRoom = GetComponent<HazardRoom>();
		checkpointTrans = transform.Find("Checkpoint");
		BoxCollider2D[] components = GetComponents<BoxCollider2D>();
		for (int i = 0; i < components.Length; i++)
		{
			components[i].gameObject.layer = ChaosCollisions.layerPlayerDetector;
		}
	}
	public void Start()
	{
		Transform parent = transform;
		while (roomScript == null && !(parent == null))
		{
			roomScript = parent.GetComponentInChildren<Room>();
			parent = parent.parent;
		}
		if (roomScript == null)
		{
			triggered = true;
			roomCleared = true;
			return;
		}
		GameObject gameObject = roomScript.gameObject;
		roomPos = roomScript.transform.position;
		retractableWalls = gameObject.GetComponentsInChildren<RetractableWall>();
		survivalRooms = (from x in gameObject.GetComponentsInChildren<SurvivalRoom>()
			orderby x.order
			select x).ToArray();
		if (survivalRooms.Length <= 1)
		{
			enemyFactories = gameObject.GetComponentsInChildren<EnemyFactory>();
		}
		else
		{
			enemyFactories = GetComponentsInChildren<EnemyFactory>();
		}
		if (enemyFactories.Length == 0)
		{
			triggered = true;
			roomCleared = true;
		}
		northGate = new GameObject();
		northGate.transform.SetParent(transform);
		northGate.name = "NorthGate";
		northGate.transform.position = roomPos;
		southGate = new GameObject();
		southGate.transform.SetParent(transform);
		southGate.transform.position = roomPos;
		southGate.name = "SouthGate";
		eastGate = new GameObject();
		eastGate.transform.SetParent(transform);
		eastGate.transform.position = roomPos;
		eastGate.name = "EastGate";
		westGate = new GameObject();
		westGate.transform.SetParent(transform);
		westGate.transform.position = roomPos;
		westGate.name = "WestGate";
	}
	public void GenerateWallCollider(MapDirections validWallType, Vector3 startPos, Vector3 endPos, GameObject gateObj)
	{
		float num = Vector2.Distance(startPos, endPos) + 1f;
		switch (validWallType)
		{
		case MapDirections.North:
		{
			BoxCollider2D boxCollider2D = gateObj.transform.Find("NorthCollider/LowerWallCollider").gameObject.AddComponent<BoxCollider2D>();
			boxCollider2D.size = new Vector2(num + 2f, 2f);
			boxCollider2D.offset = new Vector2(num / 2f, 1f);
			boxCollider2D = gateObj.transform.Find("NorthCollider/UpperWallCollider").gameObject.AddComponent<BoxCollider2D>();
			boxCollider2D.size = new Vector2(num + 2f, 5f);
			boxCollider2D.offset = new Vector2(num / 2f, 3.5f);
			boxCollider2D = gateObj.transform.Find("NorthCollider").gameObject.AddComponent<BoxCollider2D>();
			boxCollider2D.size = new Vector2(num + 2f, 6f);
			boxCollider2D.offset = new Vector2(num / 2f, 3f);
			break;
		}
		case MapDirections.South:
		{
			BoxCollider2D boxCollider2D = gateObj.AddComponent<BoxCollider2D>();
			boxCollider2D.size = new Vector2(num + 2f, 6f);
			boxCollider2D.offset = new Vector2(num / 2f, 0f);
			break;
		}
		case MapDirections.East:
		{
			startPos.x++;
			startPos.y = 0f - startPos.y + -1f;
			BoxCollider2D boxCollider2D = gateObj.AddComponent<BoxCollider2D>();
			boxCollider2D.size = new Vector2(6f, num + (float)WallGenerator.wallHeight + 1f);
			boxCollider2D.offset = new Vector2(3f, (0f - num) / 2f + 1f);
			break;
		}
		default:
		{
			startPos.y = 0f - startPos.y + -1f;
			BoxCollider2D boxCollider2D = gateObj.AddComponent<BoxCollider2D>();
			boxCollider2D.size = new Vector2(6f, num + (float)WallGenerator.wallHeight + 1f);
			boxCollider2D.offset = new Vector2(-3f, (0f - num) / 2f + 1f);
			break;
		}
		}
	}
	public bool IsEndOfWallSection(Vector3 gatePos, int conCount, List<Tile> connectionList, float roomPosZ)
	{
		if (conCount + 1 >= connectionList.Count)
		{
			return true;
		}
		Tile tile = connectionList[conCount + 1];
		if (Vector3.Distance(gatePos, new Vector3(tile.col, tile.row, roomPosZ)) > 1f)
		{
			return true;
		}
		return false;
	}
	public void SpawnVisualUnit(Vector3 position, MapDirections validWallType, ref GameObject newGate)
	{
		if (validWallType == MapDirections.North || validWallType == MapDirections.South)
		{
			newGate = Object.Instantiate(horGatePrefab, position, Quaternion.identity);
		}
		else
		{
			newGate = Object.Instantiate(vertGatePrefab, position, Quaternion.identity);
		}
		switch (validWallType)
		{
		case MapDirections.North:
			newGate.transform.SetParent(northGate.transform);
			newGate.transform.position = newGate.transform.position + northGateOffset;
			break;
		case MapDirections.South:
			newGate.transform.SetParent(southGate.transform);
			newGate.transform.position = newGate.transform.position + southGateOffset;
			break;
		case MapDirections.East:
			newGate.transform.SetParent(eastGate.transform);
			newGate.transform.Find("EastCollider").gameObject.SetActive(value: true);
			newGate.transform.position = newGate.transform.position + eastGateOffset;
			break;
		default:
			newGate.transform.SetParent(westGate.transform);
			newGate.transform.Find("WestCollider").gameObject.SetActive(value: true);
			newGate.transform.position = newGate.transform.position + westGateOffset;
			break;
		}
	}
	public void InstantiateWalls()
	{
		if (gatesInstantiated)
		{
			return;
		}
		roomScript.SetConnectionInfo();
		Vector3 zero = Vector3.zero;
		Vector3 zero2 = Vector3.zero;
		GameObject gameObject = null;
		GameObject gameObject2 = null;
		Tile tile = null;
		GameObject gameObject3 = null;
		int num = 0;
		Vector3 startPos = Vector3.zero;
		MapDirections[] array = validWallTypes;
		foreach (MapDirections mapDirections in array)
		{
			List<Tile> list = null;
			list = mapDirections switch
			{
				MapDirections.North => roomScript.topConnections, 
				MapDirections.South => roomScript.bottomConnections, 
				MapDirections.East => roomScript.rightConnections, 
				_ => roomScript.leftConnections, 
			};
			if (list == null)
			{
				continue;
			}
			num = 0;
			for (int j = 0; j < list.Count; j++)
			{
				tile = list[j];
				zero = new Vector3(tile.col, tile.row, roomPos.z);
				zero2 = new Vector3(tile.col, -tile.row, roomPos.z);
				gameObject = null;
				if (num == 0)
				{
					gameObject2 = null;
					startPos = zero;
				}
				if (mapDirections == MapDirections.North || mapDirections == MapDirections.South)
				{
					num++;
					if (num % 4 == 0)
					{
						SpawnVisualUnit(roomPos + zero2, mapDirections, ref gameObject);
						if (gameObject2 == null)
						{
							gameObject2 = gameObject;
						}
						if (IsEndOfWallSection(zero, j, list, roomPos.z))
						{
							GenerateWallCollider(mapDirections, startPos, zero, gameObject2);
							num = 0;
						}
					}
					continue;
				}
				if (num == 0)
				{
					for (int k = 1; k < WallGenerator.wallHeight; k++)
					{
						SpawnVisualUnit(roomPos + zero2 + Vector3.up * k, mapDirections, ref gameObject);
					}
				}
				num++;
				SpawnVisualUnit(roomPos + zero2, mapDirections, ref gameObject);
				if (gameObject2 == null)
				{
					gameObject2 = gameObject;
				}
				if (IsEndOfWallSection(zero, j, list, roomPos.z))
				{
					GenerateWallCollider(mapDirections, startPos, zero, gameObject2);
					num = 0;
				}
			}
		}
		gatesInstantiated = true;
	}
	public void Activate(GameObject[] gates = null, RetractableWall[] wallScripts = null)
	{
		if (triggered)
		{
			return;
		}
		triggered = true;
		EnemyFactory[] array = enemyFactories;
		foreach (EnemyFactory enemyFactory in array)
		{
			for (int j = 0; j < enemyFactory.spawnedEnemies.Count; j++)
			{
				Enemy enemy = enemyFactory.spawnedEnemies[j];
				if (roomScript.name != Level.tileGrid[enemy.lastTileRow, enemy.lastTileCol].roomStub.name)
				{
					enemyFactory.spawnedEnemies.RemoveAt(j);
					j--;
				}
			}
			enemyFactory.spawning = true;
		}
		if (gates != null && wallScripts != null)
		{
			northGate = gates[0];
			southGate = gates[1];
			eastGate = gates[2];
			westGate = gates[3];
			retractableWalls = wallScripts;
		}
		else if (roomScript != null)
		{
			InstantiateWalls();
			ToggleGates();
			RetractableWall[] array2 = retractableWalls;
			foreach (RetractableWall retractableWall in array2)
			{
				if ((retractableWall.wallType & roomScript.AllowedConnections) == retractableWall.wallType || retractableWall.wallType == MapDirections.Everything || retractableWall.wallType == MapDirections.None
				{
					retractableWall.Activate();
				}
			}
		}
		if (hazardRoom != null)
		{
			hazardRoom.HazardTriggered(overrideShutdown: true);
			if (hazardRoomList == null)
			{
				hazardRoomList = new List<HazardRoom>();
			}
			hazardRoomList.Add(hazardRoom);
		}
		if (order > 0)
		{
			return;
		}
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (checkpointTrans != null)
			{
				player.lastCheckpoint = checkpointTrans.position;
				player.fall.preFallPos = checkpointTrans.position;
			}
			if (player.playerID != targetPlayerID)
			{
				player.RequestTeleportMoveToLocation(targetPlayer.transform.position, useCheck: true);
			}
		}
		Player.OnSurvivalRoomEnter((!(checkpointTrans == null)) ? checkpointTrans.position : Vector3.zero);
		SoundManager.PlayAudio("RoomLock");
	}
	public void Disable(bool roomStatus = true, bool skipGateLogic = false)
	{
		roomCleared = roomStatus;
		if (!skipGateLogic)
		{
			RetractableWall[] array = retractableWalls;
			foreach (RetractableWall retractableWall in array)
			{
				retractableWall.Disable();
			}
			ToggleGates(enable: false);
			if (roomCleared)
			{
				StartCoroutine(PlayWinFX());
				if (onSurvivalRoomClearEventHandlers != null)
				{
					onSurvivalRoomClearEventHandlers();
				}
			}
			else
			{
				SoundManager.PlayAudio("Rumble");
			}
			foreach (HazardRoom hazardRoom in hazardRoomList)
			{
				if (hazardRoom != null)
				{
					hazardRoom.ForceShutdown();
				}
			}
		}
		if (spawnTreasureChest && roomCleared && GameController.GetAlivePlayerCount() > 0)
		{
			TreasureChest treasureChest = Globals.ChaosInst<TreasureChest>(TreasureChest.Prefab, transform.parent, transform.position);
			treasureChest.lootTableName = treasureChestLootID;
			treasureChest.preventElemental = true;
		}
	}
	public IEnumerator PlayWinFX()
	{
		yield return Globals.waitForHalf;
		SoundManager.PlayAudio("RoomVictoryUnlock");
	}
	public void ToggleGates(bool enable = true)
	{
		if (!enable)
		{
			PlayBreakEffect(northGate);
			PlayBreakEffect(southGate);
			PlayBreakEffect(eastGate, horizontal: false);
			PlayBreakEffect(westGate, horizontal: false);
		}
		northGate.SetActive(enable);
		southGate.SetActive(enable);
		eastGate.SetActive(enable);
		westGate.SetActive(enable);
	}
	private void PlayBreakEffect(GameObject gateObj, bool horizontal = true)
	{
		if (!gateObj.activeSelf)
		{
			return;
		}
		foreach (Transform item in gateObj.transform)
		{
			if (horizontal)
			{
				PoolManager.GetPoolItem<ParticleEffect>("MetalDebrisEmitter").Emit(4, item.position, ParticleEffectOverrides.StartLifeTime0p75);
				PoolManager.GetPoolItem<ParticleEffect>("MetalDebrisEmitter").Emit(4, item.position + Vector3.right + Vector3.up, ParticleEffectOverrides.StartLifeTime0p75);
				PoolManager.GetPoolItem<ParticleEffect>("MetalDebrisEmitter").Emit(4, item.position + Vector3.right * 2f + Vector3.up * 1.25f, ParticleEffectOverrides.StartLifeTime0p75);
			}
			else
			{
				PoolManager.GetPoolItem<ParticleEffect>("MetalDebrisEmitter").Emit(4, item.position, ParticleEffectOverrides.StartLifeTime0p75);
			}
		}
	}
	public void Update()
	{
		if (!triggered || roomCleared)
		{
			return;
		}
		if (ChaosStopwatch.Check(intervalStopwatchID))
		{
			intervalStopwatchID = ChaosStopwatch.Begin(checkPlayerStatusInterval);
			if (!CheckPlayers())
			{
				ResetSurvivalRooms();
			}
		}
		if (CheckSpawners())
		{
			bool skipGateLogic = order != survivalRooms.Length - 1;
			Disable(roomStatus: true, skipGateLogic);
			EnableNextRooms();
		}
	}
	public void EnableNextRooms()
	{
		for (int i = 0; i < survivalRooms.Length; i++)
		{
			if (survivalRooms[i].order == order + 1)
			{
				survivalRooms[i].hazardRoomList = hazardRoomList;
				survivalRooms[i].Activate(new GameObject[4] { northGate, southGate, eastGate, westGate }, retractableWalls);
			}
		}
	}
	public bool CheckPlayers()
	{
		Player[] playerScripts = GameController.playerScripts;
		foreach (Player player in playerScripts)
		{
			if (player != null && player.currentStateName != "Dead")
			{
				return true;
			}
		}
		return false;
	}
	private void ResetSurvivalRooms()
	{
		SurvivalRoom[] array = survivalRooms;
		foreach (SurvivalRoom survivalRoom in array)
		{
			survivalRoom.Disable(roomStatus: false, survivalRoom != this);
			survivalRoom.triggered = false;
			EnemyFactory[] array2 = survivalRoom.enemyFactories;
			foreach (EnemyFactory enemyFactory in array2)
			{
				enemyFactory.ResetFactory();
			}
		}
	}
	public bool CheckSpawners()
	{
		EnemyFactory[] array = enemyFactories;
		foreach (EnemyFactory enemyFactory in array)
		{
			if (!enemyFactory.AllEnemiesCleared())
			{
				return false;
			}
		}
		return true;
	}
}

