	public virtual void LoadNextLevel()
	{
		if (nextLevelName == string.Empty)
		{
			nextLevelName = GetCurrentTierScene();
			if (Level.isBossRushMode)
			{
				RunData.AddTimeStamp();
			}
			if (InTierScene(string.Empty))
			{
				if (GameController.stageCount > ((!Level.isBossRushMode) ? GameController.stagesPerTier : GameController.stagesPerRush))
				{
					nextLevelName = GameController.bossLevelNameDict[Application.loadedLevelName];
				}
			}
			else if (Application.loadedLevelName.Contains("BossLevel"))
			{
				GameController.stageCount = 0;
				GameController.tierCount++;
				if (Level.isBossRushMode)
				{
					switch (GameController.tierCount)
					{
					case 5:
						nextLevelName = "FinalBossLevel";
						break;
					case 6:
						nextLevelName = "TitleScreen";
						break;
					default:
						nextLevelName = GetCurrentTierScene();
						break;
					}
				}
				else
				{
					switch (GameController.tierCount)
					{
					case 3:
						nextLevelName = "FinalBossLevel";
						break;
					case 4:
						nextLevelName = "Ending";
						break;
					default:
						nextLevelName = GetCurrentTierScene();
						break;
					}
				}
			}
		}
		if (showLevelSummary)
		{
			GameController.levelSummary.Activate(nextLevelName);
		}
		else
		{
			GameController.LoadLevel(nextLevelName);
		}
	}
