using UnityEngine;
public class FireBoss : Boss
{
	public class FireBossIntroState : BossIntroState
	{
		public new FireBoss parent;
		private bool bossRevealed;
		private bool idlePausePlayed;
		private bool stretchLeftPlayed;
		private bool stretchRightPlayed;
		private bool squatPlayed;
		private float revealDelay = 0.2f;
		private float idleDelay = 0.75f;
		private ChaosQuickStopwatch revealStopwatch;
		private ChaosQuickStopwatch idleStopwatch;
		public FireBossIntroState(string newName, FSM newFSM, FireBoss newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}
		public override void OnEnter()
		{
			base.OnEnter();
			bossRevealed = false;
			idlePausePlayed = false;
			stretchLeftPlayed = false;
			stretchRightPlayed = false;
			squatPlayed = false;
			parent.anim.Play("Hidden", -1, 0f);
			PlaySpawnEffects(parent.transform.position);
			revealStopwatch = new ChaosQuickStopwatch(revealDelay);
			revealStopwatch.IsRunning = true;
		}
		public override void Update()
		{
			if (!bossRevealed)
			{
				if (!revealStopwatch.IsRunning)
				{
					parent.anim.Play("Idle", -1, 0f);
					idleStopwatch = new ChaosQuickStopwatch(idleDelay);
					idleStopwatch.IsRunning = true;
					bossRevealed = true;
				}
			}
			else
			{
				if (Level.isBossRushMode)
				{
					return;
				}
				if (!idlePausePlayed)
				{
					if (!idleStopwatch.IsRunning)
					{
						parent.anim.Play("StretchLeft", -1, 0f);
						idlePausePlayed = true;
					}
				}
				else if (parent.anim.AnimPlayed())
				{
					if (!stretchRightPlayed)
					{
						stretchRightPlayed = true;
						parent.anim.Play("StretchRight", -1, 0f);
					}
					else if (!stretchLeftPlayed)
					{
						stretchLeftPlayed = true;
						parent.anim.Play("Squat", -1, 0f);
					}
					else if (!squatPlayed)
					{
						squatPlayed = true;
						parent.anim.Play("Idle", -1, 0f);
					}
				}
			}
		}
	}
	public class FireBossOutroState(string newName, FSM newFSM, FireBoss newEnt) : State<FireBoss>(newName, newFSM, newEnt)
	{
		private bool frameSkipped;
		private bool stompPlayed;
		private float stompDelay = 0.4f;
		private float hideDelay = 0.2f;
		private ChaosQuickStopwatch hideStopwatch;
		private ChaosQuickStopwatch stompStopwatch;
		public override void OnEnter()
		{
			frameSkipped = false;
			stompPlayed = false;
			parent.anim.Play("Stomp", -1, 0f);
			stompStopwatch = new ChaosQuickStopwatch(stompDelay);
			stompStopwatch.IsRunning = true;
		}
		public override void Update()
		{
			if (!frameSkipped)
			{
				frameSkipped = true;
			}
			else if (!stompPlayed)
			{
				if (!stompStopwatch.IsRunning)
				{
					PlaySpawnEffects(parent.transform.position);
					stompPlayed = true;
					hideStopwatch = new ChaosQuickStopwatch(hideDelay);
					hideStopwatch.IsRunning = true;
				}
				else if (stompStopwatch.TimePercentage > 0.75f)
				{
					parent.anim.Play("Stomp", -1, 1f);
				}
				else
				{
					parent.anim.Play("Stomp", -1, 0f);
				}
			}
			else if (!hideStopwatch.IsRunning && parent.gameObject != null)
			{
				UnityEngine.Object.Destroy(parent.gameObject);
			}
		}
	}
	public class FireBossIdleState : BossIdleState
	{
		private string[] animNames = new string[3] { "Squat", "StretchRight", "StretchLeft" };
		private int animCount;
		private int animIndex;
		private string currentAnimName;
		private bool firstFrame;
		private AudioSource flexAudio;
		public new FireBoss parent;
		public FireBossIdleState(string newName, FSM newFSM, FireBoss newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
			animCount = animNames.Length;
		}
		public override void OnEnter()
		{
			base.OnEnter();
			PlayAnimation();
			firstFrame = true;
		}
		public override void Update()
		{
			base.Update();
			if (firstFrame)
			{
				firstFrame = false;
			}
			else if (parent.anim.AnimPlayed())
			{
				PlayAnimation();
			}
		}
		public override void OnExit()
		{
			base.OnExit();
			if (flexAudio != null)
			{
				flexAudio.Stop();
				flexAudio = null;
			}
		}
		private void PlayAnimation()
		{
			animIndex = (animIndex + UnityEngine.Random.Range(1, animCount)) % animCount;
			currentAnimName = animNames[animIndex];
			if (currentAnimName.Contains("Left"))
			{
				parent.isFacingRight = false;
				parent.facingDirection = FacingDirection.Left;
			}
			else if (currentAnimName.Contains("Right"))
			{
				parent.isFacingRight = true;
				parent.facingDirection = FacingDirection.Right;
			}
			parent.anim.PlayDirectional(currentAnimName);
			flexAudio = SoundManager.PlayAudio("FireBossFlex" + UnityEngine.Random.Range(0, 2));
		}
	}
