	public class FireBossFireComboState : BossSkillState
	{
		private float chaseMoveSpeed = 32f;
		private bool chasing;
		private float atkMoveSpeed = 20f;
		private ChaosQuickStopwatch moveStopwatch = new ChaosQuickStopwatch(0.1f);
		private int comboStopwatchID;
		private float comboInterval;
		private int maxComboCount = 3;
		private int comboCounter;
		private string roundAnimStr = "RoundhouseKick";
		private string spinAnimStr = "SpinKick";
		private bool switchAnim;
		private ChaosQuickStopwatch effectStopwatch = new ChaosQuickStopwatch(0.0625f);
		private FireBurst currentFB;
		private Vector2 currentPosition;
		public new FireBoss parent;
		public FireBossFireComboState(string newName, FSM newFSM, FireBoss newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
			useTargetHurtBox = false;
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.anim.PlayDirectional("Dash" + parent.facingDirection);
			parent.movement.EndMovement();
			parent.ToggleFloorContact(allyCollisionOn: false);
			windupTime = StdWindupTime;
			comboInterval = windupTime * 0.5f;
			comboCounter = 0;
			chasing = true;
			switchAnim = true;
			if (currentFB == null)
			{
				currentFB = ChaosInst<FireBurst>(FireBurst.Prefab);
				currentFB.SetSortLayer("Effect");
			}
		}
		public override void FixedUpdate()
		{
			if (chasing && parent.closestTargetInfo.transform != null)
			{
				parent.FaceTarget(parent.closestTargetInfo.transform.position, parent.animFacingDirections);
				parent.anim.PlayDirectional("Dash" + parent.facingDirection, -1, 0.5f);
				currentPosition = parent.transform.position;
				if (parent.movement.MoveToTarget(parent.closestTargetInfo.transform.position, 2f, chaseMoveSpeed))
				{
					chasing = false;
					parent.movement.moveVector = UpdateTargetVector(updateInfo: false, useTransform: true);
					parent.movement.EndMovement();
					parent.FaceTarget(currentPosition + targetVector, 2);
					parent.anim.Play("Slide", -1, 0f);
					comboStopwatchID = ChaosStopwatch.Begin(windupTime * 0.75f, useInterval: true, comboInterval, maxComboCount + 1);
					parent.PlayFireEffect(currentPosition);
					parent.fireWings.anim.Play("Open", -1, 0f);
				}
				if (!effectStopwatch.IsRunning)
				{
					effectStopwatch.IsRunning = true;
					SoundManager.PlayAudioWithDistance("FireArcEnd", currentPosition);
					FireBurst fireBurst = currentFB;
					int? particleCount = 5;
					Vector3? position = parent.attackOriginTrans.position + (Vector3)parent.movement.moveVector * 1.5f;
					Vector3? localEulerAngles = Globals.GetRotationVector(-parent.movement.moveVector);
					fireBurst.EmitSingle(particleCount, position, null, localEulerAngles);
				}
			}
			if (moveStopwatch.IsRunning)
			{
				parent.movement.MoveToMoveVector(atkMoveSpeed);
			}
		}
		public override void OnExit()
		{
			base.OnExit();
			parent.ToggleFloorContact();
		}
		public override void ExecuteSkill()
		{
			if (chasing)
			{
				return;
			}
			switch (ChaosStopwatch.CheckInterval(comboStopwatchID))
			{
			case StopwatchState.Ready:
				if (comboCounter == maxComboCount)
				{
					parent.movement.moveVector *= -1f;
					parent.movement.MoveToMoveVector(atkMoveSpeed);
					break;
				}
				SoundManager.PlayAudioWithDistance((comboCounter != maxComboCount - 1) ? "FlameStrikeBasic" : "FireBlast", parent.transform.position);
				parent.FaceTarget(parent.transform.position + (Vector3)targetVector, 2);
				parent.anim.Play((!switchAnim) ? spinAnimStr : roundAnimStr, -1, 0.55f);
				switchAnim = !switchAnim;
				comboCounter++;
				CreateFlameCombo();
				moveStopwatch.IsRunning = true;
				CameraController.ShakeCamera(0.5f);
				break;
			case StopwatchState.Done:
				base.ExecuteSkill();
				break;
			}
		}
		private void CreateFlameCombo()
		{
			FlameSwing flameSwing = ChaosInst<FlameSwing>(FlameSwing.Prefab, parent.attackOriginTrans.position, Globals.GetRotationQuaternion(targetVector));
			flameSwing.attack.SetAttackInfo(parent.skillCategory, skillID, comboCounter);
			flameSwing.attack.knockbackOverwriteVector = targetVector;
			if (comboCounter == maxComboCount)
			{
				FireExplosion.SpawnExplosion((Vector2)parent.attackOriginTrans.position + targetVector, 1f, 1f, 80, 100);
			}
		}
	}
	public class FireBossVacuumExplosionState : BossSkillState
	{
		private VacuumExplosion currentVS;
		private Vector2 spawnPosition;
		private float spawnDistance = 5f;
		private int totalPosition = 8;
		private int countOffset = 2;
		public new FireBoss parent;
		public FireBossVacuumExplosionState(string newName, FSM newFSM, FireBoss newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.movement.EndMovement();
			windupTime = StdWindupTime;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			exitTime = StdExitTime * 2f;
			parent.anim.Play("Stomp", -1, 0f);
		}
		public override void WindupUpdate()
		{
			parent.anim.Play("Stomp", -1, 0f);
		}
		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			if (parent.UpdateTargetInfo() != null)
			{
				spawnPosition = parent.closestTargetInfo.position;
				CreateVacuumExplosion(spawnPosition);
				for (int i = ((!(UnityEngine.Random.value < 0.5f)) ? 1 : 0); i < totalPosition; i += countOffset)
				{
					CreateVacuumExplosion(spawnPosition + spawnDistance * Globals.GetCirclePositionVector(totalPosition, i));
				}
				SoundManager.PlayAudioWithDistance("EarthExplosion", parent.transform.position);
				parent.anim.Play("Stomp", -1, 0.5f);
				parent.PlayFireEffect(parent.transform.position);
