			currentVS.fuseDuration = windupTime;
			currentVS.transform.SetParent(parent.bossObjects);
		}
	}
	public class FireBossFireDashState : BossSkillState
	{
		public NumVarStatMod dashSpeedMod;
		public NumVarStatMod dashDurationMod;
		private int maxDashCount = 3;
		private int dashCounter;
		private float dashSpeed = 32f;
		private float dashDuration = 0.25f;
		private bool dashStarted;
		private bool isDashing;
		private Attack burstAttack;
		private Vector3 fireRotationVector;
		public new FireBoss parent;
		public FireBossFireDashState(string newName, FSM newFSM, FireBoss newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
			useTargetHurtBox = false;
			dashSpeedMod = new NumVarStatMod(newName, dashSpeed, 10, VarStatModType.OverrideWithMods);
			dashDurationMod = new NumVarStatMod(newName, dashDuration, 10, VarStatModType.OverrideWithMods);
		}
		public override void OnEnter()
		{
			base.OnEnter();
			parent.anim.PlayDirectional("Dash" + parent.facingDirection);
			dashSpeedMod.modValue = dashSpeed;
			parent.movement.dashSpeedStat.AddMod(dashSpeedMod);
			dashDurationMod.modValue = dashDuration;
			parent.movement.dashDurationStat.AddMod(dashDurationMod);
			parent.ToggleFloorContact(allyCollisionOn: false);
			windupTime = StdWindupTime * 1.25f;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			dashCounter = 0;
			dashStarted = false;
			isDashing = false;
		}
		public override void FixedUpdate()
		{
			if (isDashing)
			{
				isDashing = !parent.movement.DashToTarget();
			}
		}
		public override void WindupUpdate()
		{
			FireBurst poolItem = PoolManager.GetPoolItem<FireBurst>();
			int? particleCount = 1;
			Vector3? position = parent.transform.position;
			Vector3? localEulerAngles = fireRotationVector;
			poolItem.EmitDouble(particleCount, position, null, localEulerAngles);
			if (!isDashing)
			{
				parent.FaceTarget(parent.transform.position + (Vector3)targetVector, 2);
				if (dashCounter == 0)
				{
					parent.anim.PlayDirectional("Dash" + parent.facingDirection);
				}
				else
				{
					parent.anim.Play("Slide", -1, 0f);
				}
			}
		}
		public override void ExecuteSkill()
		{
			if (isDashing)
			{
				return;
			}
			if (!dashStarted)
			{
				dashStarted = true;
				isDashing = true;
				UpdateMovementVars();
				parent.CreateFireTrail(12, 0.025f);
				parent.FaceTarget(parent.transform.position + (Vector3)targetVector, parent.animFacingDirections);
				parent.anim.PlayDirectional("Dash" + parent.facingDirection, -1, 0.5f);
				return;
			}
			parent.FaceTarget(parent.transform.position + (Vector3)targetVector, 2);
			parent.anim.Play("Slide", -1, 0f);
			parent.movement.MoveToMoveVector(dashSpeed * 0.5f);
			CreateFireBurst(parent.transform.position);
			if (dashCounter < maxDashCount)
			{
				dashStarted = false;
				UpdateTargetVector(updateInfo: true);
				windupStopwatchID = ChaosStopwatch.Begin(windupTime * 0.5f);
			}
			else
			{
				base.ExecuteSkill();
			}
		}
		public override void OnExit()
		{
			base.OnExit();
			parent.movement.EndMovement();
			parent.movement.dashSpeedStat.RemoveMod(dashSpeedMod);
			parent.movement.dashDurationStat.RemoveMod(dashDurationMod);
			parent.ToggleFloorContact();
		}
		public override Vector2 UpdateTargetVector(bool updateInfo = false, bool updateTranform = false)
		{
			targetVector = base.UpdateTargetVector(updateInfo, updateTranform);
			fireRotationVector = Globals.GetRotationVector(-targetVector);
			return targetVector;
		}
		private void UpdateMovementVars()
		{
			UpdateTargetVector(updateInfo: true);
			parent.movement.moveVector = targetVector;
			parent.movement.dashVector = targetVector;
			parent.movement.dashTimer = dashDuration;
			dashCounter++;
		}
		private void CreateFireBurst(Vector2 givenPosition)
		{
			burstAttack = ChaosInst<Attack>(Attack.CirclePrefab, givenPosition);
			burstAttack.transform.localScale = Vector3.one * 4f;

		burstAttack.transform.localScale = Vector3.one * 4f;
		burstAttack.SetAttackInfo(parent.skillCategory, skillID);
		Attack attack = burstAttack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		Attack attack2 = burstAttack;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		parent.PlayFireEffect(givenPosition);
		FireExplosion.SpawnExplosion(givenPosition, 2f, 1f, 40, 50);
		string audioID = "BlazingBlitzEnd";
		Vector2? soundOrigin = givenPosition;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		PoolManager.GetPoolItem<ParticleEffect>("BurnMarkLargeEmitter").Emit(1, givenPosition, ParticleEffectOverrides.StartLifeTimeTwo);
