	{
		base.OnEnter();
		targetVector = ((Vector2)parent.closestTargetInfo.position - parent.stageCenter).normalized;
		secondaryOffset = Globals.GetPerpendicular(targetVector) * 0.75f;
		spawnPosition = parent.stageCenter + Vector2.up - targetVector * 12f - secondaryOffset * 2f;
		startPosition = parent.stageCenter - targetVector * travelDistance;
		endPosition = parent.stageCenter + targetVector * travelDistance;
		parent.PlayFireEffect(parent.transform.position);
		parent.PlayFireEffect(startPosition);
		parent.transform.position = startPosition;
		parent.movement.moveVector = targetVector;
		parent.FaceTarget(endPosition, parent.animFacingDirections);
		PlayAnim(0);
		SoundManager.PlayAudioWithDistance("FireWallStart", parent.transform.position);
		FireBurst poolItem = PoolManager.GetPoolItem<FireBurst>();
		for (int i = 0; i < totalIntDistance; i++)
		{
			warningPosition = startPosition + targetVector * i;
			poolItem.EmitSingle(1, warningPosition);
			PoolManager.GetPoolItem<ParticleEffect>("BurnMarkSmallEmitter").Emit(1, warningPosition, ParticleEffectOverrides.StartLifeTime0p5);
		}
		windupTime = StdExitTime * 0.75f;
		windupStopwatchID = ChaosStopwatch.Begin(windupTime);
		exitTime = StdExitTime * 2f;
		shotStarted = false;
		parent.ToggleFloorContact(allyCollisionOn: false);
		arcSpeed = Mathf.Lerp(28f, 32f, currentDiffValue);
	}
	public override void WindupUpdate()
	{
		if (!shotStarted)
		{
			PlayAnim(0);
		}
	}
	public override void ExecuteSkill()
	{
		if (!shotStarted)
		{
			shotStarted = true;
			shotStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, shotInterval, shotCount);
			lerpStopwatchID = ChaosStopwatch.Begin(windupTime);
			isLerping = true;
			parent.CreateFireTrail(totalIntDistance, windupTime / (float)totalIntDistance);
			CameraController.ShakeCamera(0.6f);
		}
		switch (ChaosStopwatch.CheckInterval(shotStopwatchID))
		{
		case StopwatchState.Ready:
			shotArc = !shotArc;
			CreateFireArcs(spawnPosition, targetVector, shotArc);
			break;
		case StopwatchState.Done:
			base.ExecuteSkill();
			break;
		}
	}
	public override void FixedUpdate()
	{
		if (isLerping)
		{
			parent.transform.position = Vector2.Lerp(startPosition, endPosition, ChaosStopwatch.GetTimePercentage(lerpStopwatchID));
			PlayAnim(1);
			if (ChaosStopwatch.Check(lerpStopwatchID))
			{
				isLerping = false;
				parent.movement.MoveToMoveVector();
				parent.FaceTarget((Vector2)parent.transform.position + targetVector, 2);
				PlayAnim(2);
				CameraController.ShakeCamera();
			}
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		parent.ToggleFloorContact();
	}
	public virtual void PlayAnim(int givenStatus)
	{
		switch (givenStatus)
		{
		case 0:
			parent.anim.PlayDirectional("Dash" + parent.facingDirection);
			break;
		case 1:
			parent.anim.PlayDirectional("Dash" + parent.facingDirection, -1, 1f);
			break;
		case 2:
			if (slideAnimDirectional)
			{
				parent.anim.PlayDirectional(slideAnimName + parent.facingDirection, -1, slideAnimTime);
			}
			else
			{
				parent.anim.Play(slideAnimName, -1, slideAnimTime);
			}
			break;
		}
	}
	private void CreateFireArcs(Vector2 givenPosition, Vector2 givenVector, bool givenArc)
	{
		float num = ((!givenArc) ? 0.25f : (-0.25f));
		for (int i = 0; i < 5; i++)
		{
			currentFA = parent.GetBossPoolItem<FireArc>();
			if (currentFA == null || currentFA.transform == null)
			{
				break;
			}
			currentFA.transform.position = givenPosition + secondaryOffset * i;
			currentFA.transform.localEulerAngles = Globals.GetRotationVector(givenVector);
			currentFA.attackBox.SetAttackInfo(parent.skillCategory, skillID);
			currentFA.positiveApproach = givenArc;
			currentFA.targetVector = givenVector;
			currentFA.attackBox.knockbackOverwriteVector = givenVector;
			currentFA.arcRange = 5f + (float)i * num;
			currentFA.moveSpeed = arcSpeed + (float)((!givenArc) ? (4 - i) : i) * 2f;
			currentFA.RecycleProjectile();
		}
	}
}
public class FireBossFireBarrageState : BossSkillState
{
	private Vector2 currentPosition;
	private float spawnRange = 3f;
	private int spawnCount = 5;
	private int counter;
	private int totalCount;
	private int halfCount;
	private Transform fbContainer;
	private List<Fireball> fbList = new List<Fireball>();
	private Fireball currentFB;
	private float fireballSpeed = 32f;
	private int barrageStopwatchID;
	private int[] fireSequence = new int[5] { 2, 1, 3, 0, 4 };
	public new FireBoss parent;
	public FireBossFireBarrageState(string newName, FSM newFSM, FireBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
	}
	public override void OnEnter()
	{
		base.OnEnter();
		parent.anim.PlayDirectional("Point" + parent.facingDirection);
		windupTime = StdWindupTime * 0.75f;
		windupStopwatchID = ChaosStopwatch.Begin(windupTime);
		exitTime = StdExitTime * 1.25f;
		fbList.Clear();
		if (fbContainer == null)
		{
			fbContainer = new GameObject("FireBarrageContainer").transform;
		}
		fbContainer.SetParent(parent.bossObjects);
		totalCount = spawnCount * 2;
		halfCount = (int)((float)spawnCount * 0.5f);
		currentPosition = parent.attackOriginTrans.position;
		for (int i = -halfCount; i <= halfCount; i++)
		{
			currentFB = CreateFireball(currentPosition, targetVector);
			currentFB.transform.localPosition = spawnRange * Globals.GetCirclePositionVector(totalCount, i);
			fbList.Add(currentFB);
		}
		SoundManager.PlayAudioWithDistance("MageFireballForm", parent.transform.position);
		fbContainer.transform.position = currentPosition - targetVector;
		fbContainer.localEulerAngles = Globals.GetRotationVector(targetVector);
		CameraController.ShakeCamera(0.5f);
		barrageStopwatchID = ChaosStopwatch.Begin(windupTime, useInterval: true, windupTime * 0.25f, spawnCount);
		counter = 0;
	}
	public override void WindupUpdate()
	{
		parent.anim.PlayDirectional("Point" + parent.facingDirection);
		foreach (Fireball fb in fbList)
		{
			fb.RefreshFlightTime();
		}
	}
	public override void ExecuteSkill()
	{
		parent.anim.PlayDirectional("Point" + parent.facingDirection, -1, 0.5f);
		switch (ChaosStopwatch.CheckInterval(barrageStopwatchID))
		{
		case StopwatchState.Ready:
			ShootFireball(fbList[fireSequence[counter]]);
			SoundManager.PlayAudioWithDistance("FireballCast", parent.transform.position);
			CameraController.ShakeCamera(0.3f);
			counter++;
			break;
		case StopwatchState.Done:
			base.ExecuteSkill();
			break;
		}
	}
	private Fireball CreateFireball(Vector2 givenPosition, Vector2 givenVector)
	{
		currentFB = ChaosInst<Fireball>(Fireball.Prefab, givenPosition, Globals.GetRotationQuaternion(givenVector), fbContainer);
		currentFB.parentObject = parent.gameObject;
		currentFB.parentEntity = parent;
		currentFB.attackBox.SetAttackInfo(parent.skillCategory, skillID);
		currentFB.attackBox.gameObject.SetActive(value: false);
		currentFB.moveVector = givenVector;
		currentFB.moveSpeed = 0f;
		currentFB.flyTime = 1f;
		currentFB.goThroughWalls = true;
		return currentFB;
	}
	private void ShootFireball(Fireball givenFB)
	{
		if (!(givenFB == null))
		{
			givenFB.moveSpeed = fireballSpeed;
			givenFB.transform.SetParent(parent.bossObjects);
			givenFB.attackBox.gameObject.SetActive(value: true);
			givenFB.SetTimedIgnoreWalls(0.125f);
			FireExplosion.SpawnExplosion(givenFB.transform.position);
		}
	}
}
public class FireBossFlareFadeState : BossSkillState
{
	public NumVarStatMod dashSpeedMod;
	public NumVarStatMod dashDurationMod;
	private float dashSpeed = 32f;
	private float dashDuration = 0.125f;
	private bool dashStarted;
	private bool isDashing;
	private Vector2 perpendVector;
	private float flareSpeed;
	private float flareBias;
	private float homingDuration = 0.5f;
	public new FireBoss parent;
	public FireBossFlareFadeState(string newName, FSM newFSM, FireBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
		dashSpeedMod = new NumVarStatMod(newName, dashSpeed, 10, VarStatModType.OverrideWithMods);
		dashDurationMod = new NumVarStatMod(newName, dashDuration, 10, VarStatModType.OverrideWithMods);
	}
	public override void OnEnter()
	{
		base.OnEnter();
		targetVector = (2f * (Vector3)parent.stageCenter - parent.closestTargetInfo.position - parent.transform.position).normalized;
		parent.anim.PlayDirectional("Backhand" + parent.facingDirection);
		windupTime = StdWindupTime * 0.75f;
		windupStopwatchID = ChaosStopwatch.Begin(windupTime);
		exitTime = StdExitTime * 2f;
		dashSpeedMod.modValue = dashSpeed;
		parent.movement.dashSpeedStat.AddMod(dashSpeedMod);
		dashDurationMod.modValue = dashDuration;
		parent.movement.dashDurationStat.AddMod(dashDurationMod);
		parent.ToggleFloorContact(allyCollisionOn: false);
		dashStarted = false;
		flareSpeed = Mathf.Lerp(8f, 12f, currentDiffValue);
		flareBias = Mathf.Lerp(5f, 7f, currentDiffValue);
	}
	public override void WindupUpdate()
	{
		parent.anim.PlayDirectional("Backhand" + parent.facingDirection);
	}
	public override void ExecuteSkill()
	{
		if (!isDashing)
		{
			if (!dashStarted)
			{
				dashStarted = true;
				isDashing = true;
				parent.movement.dashVector = targetVector;
				parent.movement.dashTimer = dashDuration;
				parent.FaceTarget(parent.transform.position + (Vector3)targetVector, parent.animFacingDirections);
				parent.CreateFireTrail((int)(dashSpeed * dashDuration), 0.03f);
				return;
			}
			parent.FaceTarget(parent.closestTargetInfo.position, parent.animFacingDirections);
			parent.anim.PlayDirectional("Backhand" + parent.facingDirection, -1, 0.5f);
			parent.fireWings.anim.Play("Open", -1, 0f);
			targetVector = UpdateTargetVector(updateInfo: true);
			perpendVector = Globals.GetPerpendicular(targetVector);
			CreateFlare(targetVector);
			CreateFlare(perpendVector);
			CreateFlare(-perpendVector);
			CreateFlare((targetVector + perpendVector).normalized);
			CreateFlare((targetVector - perpendVector).normalized);
			parent.movement.moveVector = -targetVector;
			parent.movement.MoveToMoveVector(20f);
			parent.PlayFireEffect(parent.transform.position);
			base.ExecuteSkill();
		}
	}
	public override void FixedUpdate()
	{
		if (isDashing)
		{
			isDashing = !parent.movement.DashToTarget();
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		parent.movement.EndMovement();
		parent.movement.dashSpeedStat.RemoveMod(dashSpeedMod);
		parent.movement.dashDurationStat.RemoveMod(dashDurationMod);
		parent.ToggleFloorContact();
	}
	private void CreateFlare(Vector2 givenVector)
	{
		FireShuriken fireShuriken = ChaosInst<FireShuriken>(FireShuriken.Prefab, (Vector2)parent.attackOriginTrans.position + givenVector);
		fireShuriken.attackBox.SetAttackInfo(parent.skillCategory, skillID);
		fireShuriken.SetTimedIgnoreWalls(0.5f);
		fireShuriken.moveVector = givenVector;
		fireShuriken.flyTime = 3f;
		fireShuriken.moveSpeed = flareSpeed;
		fireShuriken.homingBias = flareBias;
		fireShuriken.homingDuration = homingDuration;
		if (parent.closestTargetInfo != null && parent.closestTargetInfo.hurtBoxTransform != null)
		{
			fireShuriken.targetTrans = parent.closestTargetInfo.hurtBoxTransform;
		}
	}
}
public class FireBossHeelDropState : BossUltimateState
{
	private bool jumpStarted;
	private bool fallStarted;
	private Vector2 targetLocation;
	private Vector2 currentPosition;
	private Vector2 perpendVector;
	private bool ultIsActive;
	public new FireBoss parent;
	public FireBossHeelDropState(string newName, FSM newFSM, FireBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
		useTargetHurtBox = false;
		powerUpTrans = parent.spriteRenderer.transform;
		parent.throwScript.isFallingThreshold = 0.75f;
		ThrownItem throwScript = parent.throwScript;
		throwScript.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Combine(throwScript.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
	}
	public override void OnEnter()
	{
		base.OnEnter();
		parent.FaceTarget(parent.transform.position + (Vector3)targetVector, 2);
		parent.anim.Play("Slide", -1, 0f);
		windupTime = StdWindupTime * 0.75f;
		windupStopwatchID = ChaosStopwatch.Begin(windupTime);
		exitTime = StdExitTime * 1.75f;
		parent.movement.moveVector = targetVector;
		parent.hurtBoxTransform.gameObject.SetActive(value: false);
		parent.ToggleFloorContact(allyCollisionOn: false);
		jumpStarted = false;
		fallStarted = false;
	}
	public override void ExecuteSkill()
	{
		if (!jumpStarted)
		{
			jumpStarted = true;
			StartJump();
		}
		else if (!parent.throwScript.throwComplete)
		{
			parent.anim.Play("Heel", -1, 0f);
			if (!fallStarted && parent.throwScript.isFalling)
			{
				fallStarted = true;
			}
		}
		else
		{
			parent.anim.Play("Heel", -1, 0.5f);
			base.ExecuteSkill();
		}
	}
	public override void ExitTransition()
	{
		if (!ultIsActive)
		{
			base.ExitTransition();
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		HasLanded();
		ultIsActive = false;
	}
	private void StartJump()
	{
		parent.spriteRenderer.sortingLayerName = "Effect";
		parent.PlayFireEffect(parent.transform.position);
		SoundManager.PlayAudioWithDistance("StandardJump", parent.transform.position);
		UpdateTargetVector(updateInfo: false, useTransform: true);
		if (isUltimate)
		{
			targetLocation = parent.stageCenter;
			parent.throwScript.throwHeight = 5f;
			parent.throwScript.baseFlightTime = 1f;
		}
		else
		{
			targetLocation = Globals.GetSafeLinecastVector(parent.transform.position, targetVector, Mathf.Max(0f, Vector2.Distance(parent.transform.position, parent.closestTargetInfo.position) - 2.5f), ChaosCollisions.
			parent.throwScript.throwHeight = 2.5f;
			parent.throwScript.baseFlightTime = windupTime;
		}
		parent.throwScript.ThrowToTargetVector(targetLocation);
		parent.FaceTarget(targetLocation, 2);
		parent.anim.Play("Heel", -1, 0f);
	}
	public void OnLanding()
	{
		if (!parent.fsm.currentStateName.Contains("Dead"))
		{
			currentPosition = parent.transform.position;
			parent.PlayFireEffect(currentPosition);
			parent.fireWings.anim.Play("Open", -1, 0f);
			HasLanded();
			SoundManager.PlayAudioWithDistance("MeteorExplosion", parent.transform.position);
			parent.anim.Play("Slide");
			if (isUltimate)
			{
				parent.OverdriveBurst();
				parent.StartCoroutine(MeteorRain(parent.facingDirection));
				return;
			}
			perpendVector = Globals.GetPerpendicular(targetVector) * 0.75f;
			CreateCombustionWave(currentPosition, targetVector, playAudio: true);
			CreateCombustionWave(currentPosition, (targetVector + perpendVector).normalized);
			CreateCombustionWave(currentPosition, (targetVector - perpendVector).normalized);
		}
	}
	public void HasLanded()
	{
		parent.spriteRenderer.sortingLayerName = "Actor";
		parent.hurtBoxTransform.gameObject.SetActive(value: true);
		parent.ToggleFloorContact();
	}
	private IEnumerator MeteorRain(FacingDirection givenDir)
	{
		string dropDirectionStr = "Drop" + ((givenDir != FacingDirection.Right && givenDir != FacingDirection.Left) ? string.Empty : givenDir.ToString());
		string meteorID = "FireBossMeteorStrike";
		float meteorInterval = Mathf.Max(windupTime * 0.3f, 0.05f);
		int meteorCount = (int)Mathf.Lerp(21f, 30f, currentDiffValue);
		int meteorStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, meteorInterval, meteorCount);
		int lockOnFrequency = 5;
		int lockOnCount = lockOnFrequency;
		bool lockOn = false;
		Vector2 dropLocation = Vector2.zero;
		ultIsActive = true;
		while (ultIsActive)
		{
			switch (ChaosStopwatch.CheckInterval(meteorStopwatchID))
			{
			case StopwatchState.Ready:
			{
				lockOn = lockOnCount == lockOnFrequency;
				lockOnCount = ((!lockOn) ? (lockOnCount + 1) : 0);
				dropLocation = ((!lockOn || parent.UpdateTargetInfo() == null) ? parent.stageCenter.Randomize(1f, 10f, 1.5f) : ((Vector2)parent.closestTargetInfo.position.Randomize(1f, 2f)));
				MeteorStrike currentMS = PoolManager.GetPoolItem<MeteorStrike>();
				currentMS.Initialize(dropLocation, useCast: true, useEnemyColor: true);
				currentMS.attack.SetAttackInfo(parent.skillCategory, meteorID);
				currentMS.anim.speed = 7f;
				currentMS.forceAnimDirection = dropDirectionStr;
				break;
			}
			case StopwatchState.Done:
				ultIsActive = false;
				break;
			}
			yield return null;
		}
	}
	private void CreateCombustionWave(Vector2 givenPosition, Vector2 givenVector, bool playAudio = false)
	{
		CombustionWave combustionWave = ChaosInst<CombustionWave>(CombustionWave.Prefab, givenPosition);
		combustionWave.SetSkillData(parent.skillCategory, skillID);
		combustionWave.moveVector = givenVector;
		combustionWave.maxWaveCount = 7;
		combustionWave.spawnRate = 0.075f;
		combustionWave.spacing = 1.25f;
		combustionWave.spawnAtOrigin = true;
		combustionWave.playAudio = playAudio;
	}
}
private ThrownItem throwScript;
