public override void InitFSM()
{

	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new FireBossIntroState("Intro", fsm, this));
		fsm.AddState(new FireBossOutroState("Outro", fsm, this));
		fsm.AddState(new FireBossIdleState("Idle", fsm, this));
		fsm.AddState(new FireBossDeadState("Dead", fsm, this));
		fsm.AddState(bossReadyState = new FireBossReadyState("Ready", fsm, this));
		fsm.AddState(bossHurtState = new BossHurtState("Hurt", fsm, this));
		fsm.AddState(heelState = new FireBossHeelDropState("FireBossHeelDrop", fsm, this));
		fsm.AddState(lineState = new FireBossDragonLineState("FireBossDragonLine", fsm, this));
		fsm.AddState(comboState = new FireBossFireComboState("FireBossFireCombo", fsm, this));
		fsm.AddState(barrageState = new FireBossFireBarrageState("FireBossFireBarrage", fsm, this));
		fsm.AddState(flareState = new FireBossFlareFadeState("FireBossFlareFade", fsm, this));
		fsm.AddState(vacuumState = new FireBossVacuumExplosionState("FireBossVacuumExplosion", fsm, this));
		fsm.AddState(dashState = new FireBossFireDashState("FireBossFireDash", fsm, this));
		bossUltimateState = heelState as BossUltimateState;
		fsm.ChangeState((!transitionToIntro) ? fsm.defaultStateName : "Intro");
	}
	public override void Start()
	{
		throwScript.useLineCastPosition = true;
		base.Start();
		stageCenter = myOrigin;
		InitAttackPatterns();
	}
	private void InitAttackPatterns()
	{
		attackPatternList = new List<List<BossSkillState>>();
		attackPatternList.Add(new List<BossSkillState> { comboState, barrageState, lineState, flareState, dashState });
		attackPatternList.Add(new List<BossSkillState> { heelState, lineState, barrageState, vacuumState, flareState });
		attackPatternList.Add(new List<BossSkillState> { flareState, heelState, comboState, barrageState, dashState });
		if (Level.isBossRushMode || CurrentDifficulty > 0)
		{
			attackPatternList.Add(new List<BossSkillState> { vacuumState, lineState, barrageState, comboState, dashState });
			attackPatternList.Add(new List<BossSkillState> { barrageState, flareState, vacuumState, heelState, comboState });
		}
		if (Level.isBossRushMode || CurrentDifficulty > 1)
		{
			attackPatternList.Add(new List<BossSkillState> { dashState, flareState, comboState, heelState, lineState });
			attackPatternList.Add(new List<BossSkillState> { lineState, vacuumState, dashState, heelState, barrageState });
		}
		attackPatternCount = attackPatternList.Count;
	}
	public override void Update()
	{
		base.Update();
		UpdateHairPosition();
	}
	private void UpdateHairPosition()
	{
		hairEffectTrans.position = hairSpriteTrans.position + hairEffectYOffset;
		hairSideEffectTrans.position = hairSpriteTrans.position + hairEffectYOffset;
		hairEffectSorter0.yValueOffset = 0f;
		hairEffectSorter1.yValueOffset = 0f;
		int num = (int)hairOffsetMode;
		if (hairOffsetMode == 0f || hairOffsetMode == 2f)
		{
			if (hairOffsetMode == 0f)
			{
