using System.Collections;
using System.Collections.Generic;
using UnityEngine;
public class BossRoomEventHandler : MonoBehaviour
{
	public delegate void BossPerfectEventHandler();
	private static string bossTreasureChestID = "TreasureChestBoss";
	private static string bossRushTreasureChestID = "TreasureChestBossRush";
	public Vector3 cameraLockPosition = Vector3.zero;
	public bool overrideCameraLocks;
	public bool overrideVertLockValue;
	public bool overrideHoriLockValue;
	public string triggerSFX = string.Empty;
	protected Collider2D triggerCollider;
	protected GameObject triggerWall;
	protected Vector3 triggeredPosition;
	protected GameObject exitPortalPrefab;
	protected Vector3 exitPosition;
	public static BossPerfectEventHandler bossPerfectEventHandlers;
	public string bossID = "IceBoss";
	private Dictionary<string, string> bossPrefabFilePaths = new Dictionary<string, string>
	{
		{ "IceBoss", "Assets/Prefabs/Bosses/IceBoss.prefab" },
		{ "FireBoss", "Assets/Prefabs/Bosses/FireBoss.prefab" },
		{ "EarthBoss", "Assets/Prefabs/Bosses/EarthBoss.prefab" },
		{ "AirBoss", "Assets/Prefabs/Bosses/AirBoss.prefab" },
		{ "LightningBoss", "Assets/Prefabs/Bosses/LightningBoss.prefab" },
		{ "FinalBoss", "Assets/Prefabs/Bosses/FinalBoss.prefab" }
	};
	public Vector3 bossCameraOffset;
	protected GameObject bossPrefab;
	protected Vector3 bossSpawnPosition;
	protected Boss boss;
	protected bool bossSpawned;
	protected bool bossDefeated;
	protected bool bossDespawned;
