	public string bossVictoryDialogID;
	public bool useTriggerWall = true;
	protected int alivePlayerCount;
	protected bool pvpAttempted;
	protected bool pvpStarted;
	protected bool pvpActive;
	protected Dictionary<int, int> playerOriginalHealthAmounts;
	public Vector3[] playerPvpStartLoc;
	protected bool exitSpawned;
	protected int[] playerStartHealthValues;
	protected bool playBossDialog = true;
	public virtual void Awake()
	{
		exitPortalPrefab = ChaosBundle.Get("Assets/Prefabs/Environment/ExitPortal.prefab");
	}
	public virtual void Start()
	{
		triggerCollider = GetComponent<Collider2D>();
		triggerWall = transform.Find("TriggerWall").gameObject;
		triggerWall.SetActive(value: false);
		exitPosition = transform.Find("ExitPosition").position;
		bossPrefab = ChaosBundle.Get(bossPrefabFilePaths[bossID]);
		bossSpawnPosition = transform.Find("BossSpawnPosition").position;
		playBossDialog = !Level.isBossRushMode && GameController.loopCount < 1;
		ChaosBundle.LoadBGM("Boss");
	}
	public virtual void OnTriggerEnter2D(Collider2D col)
	{
		if (!(col.gameObject.tag == "Player") || (!(col.gameObject.name == "AllyFloorContact") && !(col.gameObject.name == "IgnoreFloorContact")))
		{
			return;
		}
		triggeredPosition = col.transform.position;
		if (!triggerCollider.enabled)
		{
			return;
		}
		triggerCollider.enabled = false;
		if (triggerSFX != string.Empty)
		{
			SoundManager.PlayAudio(triggerSFX);
		}
		if (useTriggerWall)
		{
			triggerWall.SetActive(value: true);
		}
		playerStartHealthValues = new int[GameController.activePlayers.Length];
		int playerID = col.transform.parent.gameObject.GetComponent<Player>().playerID;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (player.playerID != playerID && !player.fsm.currentStateName.Contains("Dead") && !player.TeleportToPartner(playerID, showSpawnPortal: true, excludeOrigin: true))
			{
				player.TeleportToPartner(playerID);
			}
			player.lastCheckpoint = bossSpawnPosition + Vector3.down;
			playerStartHealthValues[player.playerID] = player.health.CurrentHealthValue;
		}
		if (DebugMenu.godModeOn)
		{
			playBossDialog = false;
		}
		StartCoroutine(BossIntro());
	}
	public virtual void Update()
	{
		if (!bossSpawned || exitSpawned || (!(boss == null) && !boss.fsm.currentStateName.Contains("Dead")))
		{
			return;
		}
		int num = 0;
		int num2 = 0;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			num2++;
			if ((player.fsm.currentStateName.Contains("Dead") || player.health.CurrentHealthValue <= 0) && player.inventory.GetResurrectItem() == null)
			{
				num++;
			}
		}
		if (!bossDefeated && num != num2)
		{
			bossDefeated = true;
			Player[] activePlayers2 = GameController.activePlayers;
			foreach (Player player2 in activePlayers2)
			{
				player2.dotManager.RemoveAll();
			}
			StartCoroutine(BossOutro());
		}
		else if (bossDespawned && !HandlePvP() && !exitSpawned)
		{
			exitSpawned = true;
			StartCoroutine(ActivateExitPortal());
		}
	}
	public virtual bool HandlePvP()
	{
		if (Level.isBossRushMode || !GameController.coopOn || (pvpAttempted && !pvpActive))
		{
			return false;
		}
		if (!pvpAttempted && Inventory.EitherPlayerHasItem(BuffWithFriendship.staticID))
		{
			return false;
		}
		alivePlayerCount = 0;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			if (!player.fsm.currentStateName.Contains("Dead"))
			{
				alivePlayerCount++;
			}
		}
		if (!pvpAttempted)
		{
			pvpAttempted = true;
			if (alivePlayerCount > 1)
			{
				playerOriginalHealthAmounts = new Dictionary<int, int>();
				Player[] activePlayers2 = GameController.activePlayers;
				foreach (Player player2 in activePlayers2)
				{
					playerOriginalHealthAmounts[player2.playerID] = (int)player2.health.healthStat.CurrentValue;
				}
				StartCoroutine(StartPvP());
				pvpStarted = true;
				pvpActive = true;
			}
			else
			{
				RunData.SetPvpWinner(-1);
			}
		}
		else if (pvpActive && alivePlayerCount < 2)
		{
			pvpActive = false;
			TimeScaleController.StandardFreezeIntoEaseOutTimeScale();
			Player[] activePlayers3 = GameController.activePlayers;
			foreach (Player player3 in activePlayers3)
			{
				if (!player3.fsm.currentStateName.Contains("Dead"))
				{
					RunData.SetPvpWinner(player3.playerID);
					break;
				}
			}
		}
		return pvpActive;
	}
	public virtual IEnumerator BossIntro()
	{
		CameraController camController = GameController.cameraController;
		Vector3 originalCameraPosition = ((!(cameraLockPosition == Vector3.zero)) ? cameraLockPosition : camController.transform.position);
		bool horiOnly = ((!overrideCameraLocks) ? camController.HoriMoveOnly : (!overrideHoriLockValue));
		bool vertOnly = ((!overrideCameraLocks) ? camController.VertMoveOnly : (!overrideVertLockValue));
		if (playBossDialog)
		{
			GameController.PauseAllPlayers();
			Vector3? targetLoc = bossSpawnPosition + bossCameraOffset;
			camController.OverrideAndMoveCameraToLocation(null, targetLoc, 2f, followPlayer: false, setLocks: true, vertLockStatus: true, horiLockStatus: true);
			yield return Globals.waitForOne;
		}
		boss = Object.Instantiate(bossPrefab, bossSpawnPosition, Quaternion.identity).GetComponent<Boss>();
		boss.health.invulnerable = true;
		boss.health.showDamageNumbers = false;
		yield return null;
		if (playBossDialog)
		{
			yield return new WaitForSeconds(bossSpawnDelay);
			while (!GameUI.dialogManager.HandleDialog(bossIntroDialogID, resetOnExit: true, unpauseOnComplete: false, 0.5f))
			{
				yield return null;
			}
			boss.ExitIntro();
			yield return Globals.waitForHalf;
			Vector3? targetLoc = originalCameraPosition;
			camController.OverrideAndMoveCameraToLocation(null, targetLoc, 2f, followPlayer: false, setLocks: true, horiOnly, vertOnly);
			yield return Globals.waitForOne;
			while (camController.overrideCameraUpdate)
			{
				yield return null;
			}
			GameController.PauseAllPlayers(state: false);
		}
		else
		{
			yield return Globals.waitForOne;
			boss.ExitIntro();
			Vector3? targetLoc = originalCameraPosition;
			camController.OverrideAndMoveCameraToLocation(null, targetLoc, 0.25f, !horiOnly && !vertOnly, setLocks: true, horiOnly, vertOnly);
			yield return Globals.waitForHalf;
		}
		yield return null;
		boss.fsm.ChangeState(boss.bossReadyState.name);
		boss.health.invulnerable = false;
		boss.health.showDamageNumbers = true;
		bossSpawned = true;
		SoundManager.PlayBGM("Boss");
	}
	public virtual IEnumerator BossOutro()
	{
		boss.health.invulnerable = true;
		boss.health.showDamageNumbers = false;
		CheckForPerfectFight();
		GameController.stageTitleUI.AnnounceVictory();
		yield return Globals.waitForOne;
		SoundManager.PlayBGM(string.Empty);
		if (playBossDialog)
		{
			while (!GameUI.dialogManager.HandleDialog(bossVictoryDialogID, resetOnExit: true, unpauseOnComplete: true, 0.5f))
			{
				yield return null;
			}
		}
		boss.fsm.ChangeState("Outro");
		while (boss != null)
		{
			yield return null;
		}
		bossDespawned = true;
	}
	public virtual IEnumerator StartPvP()
	{
		StageTitleUI stageTitleUI = GameController.stageTitleUI;
		string uIText = TextManager.GetUIText("bossRoom-pvpWait");
		float duration = 2f;
		Color? textColor = Color.red;
		stageTitleUI.Announce(uIText, duration, 60, textColor, null, showUnderline: false, 1f, 0f, numberMode: false, StageTitleUI.redOutlineColor);
		while (TimeScaleController.delayInProgress)
		{
			yield return null;
		}
		yield return new WaitForSeconds(3f);
		GameUI.BroadcastNoticeMessage(" ", 1f);
		StageTitleUI stageTitleUI2 = GameController.stageTitleUI;
		uIText = TextManager.GetUIText("bossRoom-pvpReady");
		duration = 2f;
		textColor = Color.red;
		stageTitleUI2.Announce(uIText, duration, 60, textColor, null, showUnderline: false, 1f, 0f, numberMode: false, StageTitleUI.redOutlineColor);
		GameController.cameraController.disablePlayerTracking = true;
		Vector3 cameraPos = new Vector3(0f, 0f, GameController.cameraController.transform.position.z);
		int startLocCounter = 0;
		Vector3[] array = playerPvpStartLoc;
		for (int i = 0; i < array.Length; i++)
		{
			Vector3 vector = array[i];
			startLocCounter++;
			cameraPos.x += vector.x;
			cameraPos.y += vector.y;
		}
		if (startLocCounter > 0)
		{
			cameraPos.x /= startLocCounter;
			cameraPos.y /= startLocCounter;
		}
		cameraPos += Vector3.up;
		GameController.cameraController.transform.position = cameraPos;
		int pCounter = 0;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			player.health.invulnerable = true;
			player.health.RestoreHealth(1, showDisplayText: false, playSound: true, fullyRestoreHealth: true, useHealEnterEvent: false);
			player.spawnGhostOnDeath = false;
			player.OverdriveProgress = 0f;
			player.ToggleOverdriveEffects(status: false);
			player.ResetPlayerCooldowns();
			player.facingDirection = ((pCounter % 2 == 0) ? FacingDirection.Right : FacingDirection.Left);
			player.transform.position = playerPvpStartLoc[pCounter];
			Player.SpawnAllyPortal(playerPvpStartLoc[pCounter]);
			pCounter++;
		}
		GameController.PauseAllPlayers();
		yield return new WaitForSeconds(3f);
		GameController.stageTitleUI.Announce("3", 0f, 90, Color.white, null, showUnderline: false, 1f, 0f, numberMode: true);
		SoundManager.PlayAudio("Woosh");
		yield return Globals.waitForOne;
		GameController.stageTitleUI.Announce("2", 0f, 100, Color.white, null, showUnderline: false, 1f, 0f, numberMode: true);
		SoundManager.PlayAudio("Woosh");
		yield return new WaitForSeconds(0.4f);
		Player[] activePlayers2 = GameController.activePlayers;
		foreach (Player player2 in activePlayers2)
		{
			player2.anim.Play("ForehandRight", -1, 0f);
		}
		yield return new WaitForSeconds(0.6f);
		GameController.stageTitleUI.Announce("1", 0f, 110, Color.white, null, showUnderline: false, 1f, 0f, numberMode: true);
		Player[] activePlayers3 = GameController.activePlayers;
		foreach (Player player3 in activePlayers3)
		{
			player3.anim.Play("BackhandRight", -1, 0f);
		}
		SoundManager.PlayAudio("Woosh");
		yield return Globals.waitForOne;
		SoundManager.PlayBGM("Boss");
		GameController.stageTitleUI.AnnounceFight();
		CameraController.ShakeCamera(0.75f);
		yield return Globals.waitForQuarter;
		while (GameController.stageTitleUI.AnimIsPlaying(0.8f))
		{
			yield return null;
		}
		Player[] activePlayers4 = GameController.activePlayers;
		foreach (Player player4 in activePlayers4)
		{
			player4.health.invulnerable = false;
		}
		GameController.PauseAllPlayers(state: false);
		GameController.cameraController.disablePlayerTracking = false;
		SoundManager.PlayAudio("MetalBell");
		GameController.TogglePvpMode(pvpStatus: true);
	}
	public virtual IEnumerator ActivateExitPortal()
	{
		SoundManager.PlayBGM(string.Empty);
		Object.Instantiate(TreasureChest.Prefab, bossSpawnPosition, Quaternion.identity).GetComponent<TreasureChest>().lootTableName = ((!Level.isBossRushMode) ? bossTreasureChestID : bossRushTreasureChestI
		SoundManager.PlayAudio("StageVictory");
		if (pvpStarted)
		{
			GameController.stageTitleUI.AnnounceVictory();
			yield return new WaitForSeconds(1.5f);
			Player[] activePlayers = GameController.activePlayers;
			foreach (Player player in activePlayers)
			{
				if (player.fsm.currentStateName.Contains("Dead"))
				{
					player.ResetPlayer(originPosition: false);
				}
				player.health.healthStat.CurrentValue = playerOriginalHealthAmounts[player.playerID];
				player.spawnGhostOnDeath = true;
			}
		}
		if (pvpAttempted)
		{
			GameController.TogglePvpMode(pvpStatus: false);
		}
		float exitSpawnTime = 1.5f;
		string animName = "Draw";
		Vector3 spawnPos = exitPosition;
		bool disableWithParentVal = false;
		CastingCirclePool.Spawn(animName, spawnPos, disableWithParentVal, null, trackParentVal: true, useCastTimeVal: true, exitSpawnTime, 0f, 0f, null, exitSpawnTime);
		yield return new WaitForSeconds(exitSpawnTime);
		Object.Instantiate(exitPortalPrefab, exitPosition, Quaternion.identity);
		PoolManager.GetPoolItem<AnimEffect>("TeleportEffect").Play(exitPosition, string.Empty, 0.125f, default, 1f, 1.5f);
		yield return null;
	}
	public virtual void CheckForPerfectFight()
	{
		bool flag = false;
		Player[] activePlayers = GameController.activePlayers;
		foreach (Player player in activePlayers)
		{
			flag = true;
			if (player.health.CurrentHealthValue < playerStartHealthValues[player.playerID])
			{
				flag = false;
				break;
			}
		}
		if (flag)
		{
			AchievementManager.UnlockAchievement(Achievement.PerfectBoss, forceUnlock: true);
			if (bossPerfectEventHandlers != null)
			{
				bossPerfectEventHandlers();
			}
		}
	}
}

