public class IceBossIceDashState : BossSkillState
{
	private int spawnCount = 5;
	private int waveCount = 40;
	private Vector2 movementVector;
	private Transform targetTransform;
	private IceWaveBase currentIW;
	private IceWaveBase mainIW;
	private List<IceWaveBase> iwList = new List<IceWaveBase>();
	private Transform containerTrans;
	private List<Transform> followTransList = new List<Transform>();
	private bool iceWaveSpawned;
	private bool iceWaveDone;
	private bool followWave;
	private Vector2 followPosition;
	private ChaosQuickStopwatch activateStopwatch = new ChaosQuickStopwatch();
	public new IceBoss parent;
	public IceBossIceDashState(string newName, FSM newFSM, IceBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
	}
	public override void OnEnter()
	{
		base.OnEnter();
		parent.anim.Play("Fortify", -1, 0f);
		parent.iceWheelAnim.Play("Hide", -1, 0f);
		windupTime = StdWindupTime;
		windupStopwatchID = ChaosStopwatch.Begin(windupTime * 1.5f);
		exitTime = StdExitTime * 1.5f;
		targetTransform = parent.closestTargetInfo.transform;
		CreateContainer();
		iceWaveSpawned = false;
		iceWaveDone = false;
		followWave = true;
		parent.ToggleFloorContact(allyCollisionOn: false);
	}
	public override void ExecuteSkill()
	{
		if (!iceWaveSpawned)
		{
			iceWaveSpawned = true;
			CreateAllIceWaves();
			return;
		}
		iceWaveDone = mainIW == null || !mainIW.IsSpawning;
		if (!iceWaveDone)
		{
			containerTrans.position = mainIW.activationPosition;
			movementVector = mainIW.moveVector;
			containerTrans.localEulerAngles = Globals.GetRotationVector(movementVector);
			if (!followWave)
			{
				return;
			}
			followWave = (float)mainIW.wavesElapsed < 0.75f * (float)waveCount;
			mainIW.homing = followWave;
			if (followWave)
			{
				return;
			}
			mainIW.moveVector = (movementVector + UpdateTargetVector(updateInfo: false, useTransform: true)).normalized;
			{
				foreach (IceWaveBase iw in iwList)
				{
					if (iw != null)
					{
						iw.spawnWaveThroughStopLayermask = false;
					}
				}
				return;
			}
		}
		if (mainIW != null)
		{
			IceWaveBase iceWaveBase = mainIW;
			iceWaveBase.activateEventHandler = (IceWaveBase.ActivateEventHandler)Delegate.Remove(iceWaveBase.activateEventHandler, new IceWaveBase.ActivateEventHandler(OnWaveActivate));
		}
		parent.anim.Play("Unfortify", -1, 0.15f);
		parent.iceWheelAnim.Play("Open", -1, 0f);
		base.ExecuteSkill();
	}
	public override void FixedUpdate()
	{
		if (iceWaveSpawned && !iceWaveDone && followWave)
		{
			parent.rigidbody2D.MovePosition(Vector2.Lerp(parent.transform.position, containerTrans.position, activateStopwatch.TimePercentage));
		}
	}
	private void OnWaveActivate()
	{
		activateStopwatch.IsRunning = true;
	}
	public override void OnExit()
	{
		base.OnExit();
		parent.ToggleFloorContact();
		parent.FortifyStatus(0);
	}
	private void CreateContainer()
	{
		if (!(containerTrans == null))
		{
			return;
		}
		containerTrans = new GameObject("IceWaveContainer").transform;
		containerTrans.SetParent(parent.bossObjects);
		for (int i = 0; i < spawnCount; i++)
		{
			Transform transform = new GameObject().transform;
			transform.SetParent(containerTrans);
			followTransList.Add(transform);
			switch (i)
			{
			case 0:
				transform.localPosition = new Vector2(0f, 1f);
				break;
			case 1:
				transform.localPosition = new Vector2(-1f, 0.5f);
				break;
			case 2:
				transform.localPosition = new Vector2(1f, 0.5f);
				break;
			case 3:
				transform.localPosition = new Vector2(-2f, -1f);
				break;
			case 4:
				transform.localPosition = new Vector2(2f, -1f);
				break;
			}
		}
	}
	private void CreateAllIceWaves()
	{
		containerTrans.position = parent.transform.position;
		containerTrans.localEulerAngles = Globals.GetRotationVector(UpdateTargetVector(updateInfo: true));
		iwList.Clear();
		mainIW = CreateIceWave(targetTransform, setAsSpawn: false);
		IceWaveBase iceWaveBase = mainIW;
		iceWaveBase.activateEventHandler = (IceWaveBase.ActivateEventHandler)Delegate.Remove(iceWaveBase.activateEventHandler, new IceWaveBase.ActivateEventHandler(OnWaveActivate));
		IceWaveBase iceWaveBase2 = mainIW;
		iceWaveBase2.activateEventHandler = (IceWaveBase.ActivateEventHandler)Delegate.Combine(iceWaveBase2.activateEventHandler, new IceWaveBase.ActivateEventHandler(OnWaveActivate));
		activateStopwatch.SetDelay(mainIW.spawnRate);
		for (int i = 0; i < spawnCount; i++)
		{
			CreateIceWave(followTransList[i], setAsSpawn: true);
		}
	}
	private IceWaveBase CreateIceWave(Transform givenTrans, bool setAsSpawn)
	{
		currentIW = ChaosInst<IceWaveBase>(IceWaveBase.Prefab);
		if (setAsSpawn)
		{
			currentIW.spawnTransform = givenTrans;
			currentIW.disableLights = true;
			iwList.Add(currentIW);
		}
		else
		{
			currentIW.homing = true;
			currentIW.homingBias = 7;
			currentIW.targetTrans = givenTrans;
		}
		currentIW.SetSkillData(parent.skillCategory, skillID);
		currentIW.spawnRate = Mathf.Lerp(0.09f, 0.07f, currentDiffValue);
		currentIW.wavePoolSize = 10;
		currentIW.maxWaveCount = waveCount;
		currentIW.ignoreWaveCollisions = true;
		currentIW.spawnWaveThroughStopLayermask = true;
		currentIW.spawnReturnWave = false;
		return currentIW;
	}
}
