public class AirBossAirRailState : BossUltimateState
{
	private int waveStopwatchID;
	private int waveCount;
	private float waveInterval = 0.55f;
	private bool waveStarted;
	private int shotsPerWave = 8;
	private int maxShotCount = 3;
	private int shotCounter;
	private ChaosQuickStopwatch lockStopwatch = new ChaosQuickStopwatch(0.125f);
	private bool lockStarted;
	private bool lockCompleted;
	private ChaosQuickStopwatch delayStopwatch = new ChaosQuickStopwatch(0.125f);
	private bool moveCompleted;
	private ParticleEffect railEffect;
	private WindArcherChargedArrow currentCA;
	private float atkSpeed = 100f;
	private int atkLevel = 1;
	private bool dashStarted;
	private bool isDashing;
	private float ultWidthRange = 1.75f;
	private int ultAimIndex;
	private int ultMaxIndex = 12;
	private ParticleEffect chargeEffect;
	private Vector2 currentPosition;
	private Vector2 currAirPos;
	public new AirBoss parent;
	private WaitForSeconds waitForWarnInterval = new WaitForSeconds(0.01f);
	private WaitForSeconds waitForShotInterval = new WaitForSeconds(0.0625f);
	public AirBossAirRailState(string newName, FSM newFSM, AirBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
		parent.CreateBossPool<WindArcherChargedArrow>(WindArcherChargedArrow.Prefab, 20);
		SetBossPoolVars();
	}
	private void SetBossPoolVars()
	{
		GenericPool<WindArcherChargedArrow> bossPool = parent.GetBossPool<WindArcherChargedArrow>(typeof(WindArcherChargedArrow));
		int itemCount = bossPool.ItemCount;
		for (int i = 0; i < itemCount; i++)
		{
			currentCA = bossPool.GetItem();
			currentCA.destroyOnDisable = false;
			currentCA.ResetProjectile();
		}
	}
	public override void OnEnter()
	{
		base.OnEnter();
		windupTime = StdWindupTime * 0.5f;
		exitTime = StdExitTime;
		windupStopwatchID = ChaosStopwatch.Begin(windupTime);
		UpdateTargetVector(updateInfo: true);
		if (isUltimate)
		{
			waveCount = (int)Mathf.Lerp(5f, 7f, currentDiffValue);
			ultAimIndex = UnityEngine.Random.Range(0, ultMaxIndex);
			waveStarted = false;
			atkLevel = 2;
			parent.anim.Play("Volley", -1, 0f);
		}
		else
		{
			lockStopwatch.SetDelay(windupTime * 1.25f);
			delayStopwatch.SetDelay(windupTime * 0.5f);
			dashStarted = false;
			isDashing = false;
			shotCounter = 0;
			atkLevel = 1;
		}
	}
	public override void FixedUpdate()
	{
		if (isDashing)
		{
			isDashing = !parent.movement.DashToTarget();
		}
	}
	public override void ExecuteSkill()
	{
		if (isUltimate)
		{
			if (!waveStarted)
			{
				waveStarted = true;
				waveStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, waveInterval, waveCount);
			}
			switch (ChaosStopwatch.CheckInterval(waveStopwatchID))
			{
			case StopwatchState.Ready:
				parent.StartCoroutine(CreateRailVolley());
				break;
			case StopwatchState.Done:
				exitTime *= 3.25f;
				base.ExecuteSkill();
				parent.anim.Play("VolleyEnd", -1, 0f);
				break;
			}
			return;
		}
		if (!dashStarted)
		{
			dashStarted = true;
			isDashing = true;
			lockStarted = false;
			parent.movement.dashVector = GetDashVector();
			parent.FaceTarget(parent.transform.position + (Vector3)parent.movement.dashVector);
			parent.anim.PlayDirectional("Dash" + parent.facingDirection);
			SoundManager.PlayWithDistAndSPR("WindBlastSharp", parent.transform.position);
		}
		if (isDashing)
		{
			return;
		}
		if (!lockStarted)
		{
			lockStarted = true;
			lockCompleted = false;
			lockStopwatch.IsRunning = true;
			InitLockOn();
		}
		if (!lockCompleted)
		{
			if (!lockStopwatch.IsRunning)
			{
				parent.anim.PlayDirectional("Point" + parent.facingDirection, -1, 1f);
				parent.targetLine.IsVisible(status: false);
				parent.movement.moveVector = targetVector;
				parent.movement.MoveToMoveVector(60f);
				ShootRailArrow(parent.attackOriginTrans.position, targetVector);
				if (chargeEffect != null)
				{
					chargeEffect.Stop();
					chargeEffect.effectEmitter.Clear();
				}
				lockCompleted = true;
				delayStopwatch.IsRunning = true;
				moveCompleted = false;
			}
		}
		else if (!moveCompleted)
		{
			if (!delayStopwatch.IsRunning)
			{
				moveCompleted = true;
				delayStopwatch.IsRunning = true;
				parent.movement.EndMovement();
			}
		}
		else if (!delayStopwatch.IsRunning)
		{
			shotCounter++;
			if (shotCounter < maxShotCount)
			{
				dashStarted = false;
			}
			else
			{
				base.ExecuteSkill();
			}
		}
	}
	public override void OnExit()
	{
		base.OnExit();
		parent.targetLine.IsVisible(status: false);
		if (chargeEffect != null)
		{
			chargeEffect.Stop();
			chargeEffect.effectEmitter.Clear();
		}
	}
	private Vector2 GetDashVector()
	{
		return (parent.stageCenter + UnityEngine.Random.insideUnitCircle * 3f - (Vector2)parent.transform.position).normalized;
	}
	private void InitLockOn()
	{
		UpdateTargetVector(updateInfo: false, useTransform: true);
		parent.FaceTarget(parent.transform.position + (Vector3)targetVector);
		parent.anim.PlayDirectional("Point" + parent.facingDirection);
		parent.movement.moveVector = -targetVector;
		parent.movement.MoveToMoveVector(10f);
		parent.targetLine.transform.position = parent.attackOriginTrans.position + (Vector3)targetVector * 1.25f;
		parent.targetLine.aimVector = targetVector;
		parent.targetLine.IsVisible(status: true);
		chargeEffect = PoolManager.GetPoolItem<ParticleEffect>("WindDrillEffect");
		chargeEffect.followTransform = parent.rightHandTrans;
		chargeEffect.Play(30f, parent.rightHandTrans.position, null, 0.15f, null, Globals.GetRotationVector(targetVector));

