public class HealthProxy : Health
{
	public Health parentHealth;
	private int eleDmgMulti;
	public override void Start()
	{
		ignorePlayerEndStats = true;
		base.Start();
	}
	public override float GetElementalDamageModifier(ElementType damageType)
	{
		if (parentHealth == null || damageType == ElementType.Neutral)
		{
			return 1f;
		}
		eleDmgMulti = 0;
		if (entityElement == damageType)
		{
			eleDmgMulti = -2;
		}
		else if (Health.eleWheelDict.ContainsKey(entityElement) && Health.eleWheelDict[entityElement] == damageType)
		{
			eleDmgMulti = 2;
		}
		else if (Health.eleWheelDict.ContainsKey(damageType) && Health.eleWheelDict[damageType] == entityElement)
		{
			eleDmgMulti = -1;
		}
		return 1f + (float)eleDmgMulti * Health.baseEleBoostValue;
	}
	public override bool TakeDamage(AttackInfo givenAttackInfo, Entity attackEntity, bool preCalc)
	{
		base.TakeDamage(givenAttackInfo, attackEntity, preCalc);
		if (parentHealth == null)
		{
			return false;
		}
		givenAttackInfo.showDamageNumber = false;
		givenAttackInfo.showDamageEffect = false;
		givenAttackInfo.shakeCamera = false;
		givenAttackInfo.canHitStun = false;
		givenAttackInfo.rootChance = 0f;
		givenAttackInfo.burnChance = 0f;
		givenAttackInfo.slowChance = 0f;
		givenAttackInfo.poisonChance = 0f;
		givenAttackInfo.shockChance = 0f;
		givenAttackInfo.freezeChance = 0f;
		givenAttackInfo.chaosChance = givenAttackInfo.chaosChance;
		givenAttackInfo.chaosLevel = givenAttackInfo.chaosLevel;
		return parentHealth.TakeDamage(givenAttackInfo, attackEntity, preCalc);
	}
}

