	public class FinalBossIntroState : BossIntroState
	{
		private static Vector2 stageOffset = Vector2.up * 0.5f;
		private Vector2 portalPos;
		private Health parentHealth;
		private NumVarStatMod chaosHealthIncrease = new NumVarStatMod("FinalBossChaos", 1750f, 5, VarStatModType.Override);
		private NumVarStatMod superHealthIncrease = new NumVarStatMod("FinalBossSuper", 3000f, 10, VarStatModType.Override);
		private ChaosQuickStopwatch healthStopwatch = new ChaosQuickStopwatch(1.5f);
		private bool animFrameSkipped;
		private bool standAnimPlayed;
		private bool powerUpLoopPlayed;
		private bool powerUpLoopDone;
		private bool powerDownSFXPlayed;
		private ChaosSwordSummon curSwordSummon;
		private AudioSource superChargeSFX;
		public new FinalBoss parent;
		public FinalBossIntroState(string newName, FSM newFSM, FinalBoss newEnt)
			: base(newName, newFSM, newEnt)
		{
			parent = newEnt;
			parentHealth = parent.health;
		}
		public override void OnEnter()
		{
			animFrameSkipped = false;
			standAnimPlayed = false;
			powerUpLoopPlayed = false;
			powerUpLoopDone = false;
			powerDownSFXPlayed = false;
			superChargeSFX = null;
			if (fsm.previousStateName == "Dead")
			{
				portalPos = parent.stageCenter + stageOffset;
				if (parent.chaosMode)
				{
					parent.chaosMode = false;
					chaosHealthIncrease.modValue = 1750 + GameController.CurrentDifficulty * 100;
					parentHealth.healthStat.AddMod(chaosHealthIncrease);
					SpawnPortal poolItem = PoolManager.GetPoolItem<SpawnPortal>();
					poolItem.Spawn(parent.transform.position, SpawnPortal.enemyColor);
					poolItem.Spawn(portalPos, SpawnPortal.enemyColor);
					parent.transform.position = portalPos;
					healthStopwatch.IsRunning = true;
					parent.anim.Play("StandUpHoodless", -1, 0f);
				}
				else if (!parent.superMode)
				{
					parent.superMode = true;
					superHealthIncrease.modValue = 2000 + GameController.CurrentDifficulty * 100;
					parentHealth.healthStat.AddMod(superHealthIncrease);
					SpawnPortal poolItem2 = PoolManager.GetPoolItem<SpawnPortal>();
					poolItem2.Spawn(parent.transform.position, SpawnPortal.enemyColor);
					poolItem2.Spawn(portalPos, SpawnPortal.enemyColor);
					parent.transform.position = portalPos;
					healthStopwatch.IsRunning = true;
					parent.anim.Play("StandUp", -1, 0f);
					parent.attackIndexCurrentMax = 6;
				}
			}
			else
			{
				parent.anim.Play("IdleArmsCrossedHoodless", -1, 0f);
			}
		}
		public override void Update()
		{
			if (parent.chaosMode && !parent.superMode)
			{
				return;
			}
			parentHealth.healthStat.CurrentValue = Mathf.Lerp(0f, parentHealth.healthStat.ModifiedValue, healthStopwatch.TimePercentage);
			if (!standAnimPlayed)
			{
				if (!animFrameSkipped)
				{
					animFrameSkipped = true;
				}
				else if (parent.anim.AnimPlayed(1.25f))
				{
					standAnimPlayed = true;
					if (parent.superMode)
					{
						curSwordSummon = Globals.ChaosInst<ChaosSwordSummon>(ChaosSwordSummon.Prefab, null, parent.transform.position);
						curSwordSummon.enabled = false;
						curSwordSummon.anim.Play("PowerUpIdle", -1, 0f);
						parent.anim.Play("PowerUp", -1, 0f);
						SoundManager.PlayAudio("ChaosOpen");
						superChargeSFX = SoundManager.PlayAudio("ChaosBeamLoop");
					}
					else
					{
						parent.anim.Play("Hood", -1, 0f);
					}
				}
			}
			else
			{
				if (!parent.superMode)
				{
					return;
				}
				if (!powerUpLoopPlayed && parent.anim.AnimPlayed())
				{
					powerUpLoopPlayed = true;
					CameraController.ShakeCamera(0.5f);
					curSwordSummon.anim.Play("PowerUp", -1, 0f);
					parent.spriteRenderer.material = parent.superMaterial;
					parent.superAuraObj.SetActive(value: true);
					parent.anim.Play("PowerUpLoop", -1, 0f);
					SoundManager.PlayAudio("PlayerOverdriveActivate");
					SoundManager.PlayAudio("ChaosFormLong");
					parent.SetInvulOutlineColor();
				}
				else
				{
					if (powerUpLoopDone)
					{
						return;
					}
					if (!parent.anim.AnimPlayed(8f))
					{
						if (superChargeSFX != null && !superChargeSFX.isPlaying)
						{
							superChargeSFX = SoundManager.PlayAudio("ChaosBeamLoop");
						}
						if (!powerDownSFXPlayed && parent.anim.AnimPlayed(6.5f))
						{
							powerDownSFXPlayed = true;
							SoundManager.PlayAudio("ChaosWarble", 1f, ignoreTimeRestriction: false, 0.2f);
						}
						return;
					}
					powerUpLoopDone = true;
					if (superChargeSFX != null && superChargeSFX.isPlaying)
					{
						superChargeSFX.Stop();
						superChargeSFX = null;
					}
					parent.anim.Play("BackhandDown", -1, 0.2f);
					SoundManager.PlayAudio("WindSlashBasic");
					SoundManager.PlayAudio("SlashIntro");
				}
			}
		}
		public override void OnExit()
		{
			if (curSwordSummon != null)
			{
				UnityEngine.Object.Destroy(curSwordSummon.gameObject);
			}
			parent.health.healthStat.CurrentValue = parent.health.healthStat.ModifiedValue;
			if (parent.bossUltimateState != null)
			{
				parent.bossUltimateState.UltIsReady = false;
			}
		}
	}
