public class LightningBossShockBlenderState : BossSkillState
{
	private List<OrbMetalFamiliar> orbList = new List<OrbMetalFamiliar>();
	private OrbMetalFamiliar currentOF;
	private Vector2 currentPosition;
	private bool orbsSpawned;
	private int spawnCount = 3;
	private float spawnRange = 3f;
	private bool standPlayed;
	private bool crossArmPlayed;
	private NumVarStatMod healthMod;
	private bool dashToPosCompleted;
	public new LightningBoss parent;
	public LightningBossShockBlenderState(string newName, FSM newFSM, LightningBoss newEnt)
		: base(newName, newFSM, newEnt)
	{
		parent = newEnt;
		healthMod = new NumVarStatMod(newName, 25f, 10, VarStatModType.Override, fillToNewMax: true);
	}
	public override void OnEnter()
	{
		if (!parent.DashToPosition(name, BlenderGuyPos))
		{
			dashToPosCompleted = true;
			base.OnEnter();
			parent.SetColliderStatus(givenStatus: true, partnerStatus: true);
			parent.Partner.MoveAndAnimate(BlenderGirlPos, "FistPump", givenHoldAnim: true);
			orbsSpawned = false;
			standPlayed = false;
			crossArmPlayed = false;
			windupTime = StdWindupTime * 0.75f;
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
			exitTime = StdExitTime * 3f;
			CleanOrbList();
			if (orbList.Count > 0)
			{
				BurstAllOrbs(givenStatus: true, windupTime * 2f);
			}
			parent.anim.Play("GroundSlam", -1, 0f);
		}
	}
	public override void WindupUpdate()
	{
		if (!orbsSpawned)
		{
			parent.anim.Play("GroundSlam", -1, 0f);
		}
	}
	public override void Update()
	{
		base.Update();
		if (!exitQueued)
		{
			return;
		}
		if (!standPlayed)
		{
			if (ChaosStopwatch.GetTimePercentage(exitStopwatchID) > 0.3f)
			{
				standPlayed = true;
				parent.anim.Play("Stand", -1, 0f);
			}
		}
		else if (!crossArmPlayed && ChaosStopwatch.GetTimePercentage(exitStopwatchID) > 0.6f)
		{
			crossArmPlayed = true;
			parent.anim.Play("CrossArms", -1, 0f);
		}
	}
	public override void ExecuteSkill()
	{
		if (!orbsSpawned)
		{
			orbsSpawned = true;
			SummonAllOrbs();
			parent.anim.Play("GroundSlam", -1, 0.5f);
			DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
			int particleCount = 40;
			float scale = 0.5f;
			Vector3? emitPosition = parent.transform.position;
			poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			PoolManager.GetPoolItem<ParticleEffect>("FloorCrater").Emit(1, parent.transform.position);
			CameraController.ShakeCamera(0.25f);
			windupStopwatchID = ChaosStopwatch.Begin(windupTime);
		}
		else
		{
			base.ExecuteSkill();
			parent.Partner.PlayAnim("FistPump", 1f);
			BurstAllOrbs(givenStatus: false, 0f, emitHitEffect: true);
		}
	}
	public override void OnExit()
	{
		if (dashToPosCompleted)
		{
			dashToPosCompleted = false;
			base.OnExit();
		}
	}
	private void SummonAllOrbs()
	{
		currentPosition = parent.transform.position;
		for (int i = 0; i < spawnCount; i++)
		{
			SummonMetalOrb(currentPosition + spawnRange * Globals.GetCirclePositionVector(spawnCount, i));
		}
	}
	private void SummonMetalOrb(Vector2 givenPosition)
	{
		currentOF = (OrbMetalFamiliar)Enemy.Spawn("OrbMetalFamiliar", givenPosition, parent.transform.parent, dropLoot: false, alerted: true, spawnCard: false, survivalMode: false, overrideCountDeath: true
		currentOF.parentSummoner = parent.gameObject;
		currentOF.summoned = true;
		currentOF.health.healthStat.AddMod(healthMod);
		currentOF.attack.SetAttackInfo(parent.skillCategory, skillID);
		currentOF.skillCategory = parent.skillCategory;
		currentOF.attackSkillID = skillID;
		orbList.Add(currentOF);
	}
	private void CleanOrbList()
	{
		for (int num = orbList.Count - 1; num >= 0; num--)
		{
			if (orbList[num] == null)
			{
				orbList.RemoveAt(num);
			}
		}
	}
	private void BurstAllOrbs(bool givenStatus, float burstDelay = 0f, bool emitHitEffect = false)
	{
		for (int num = orbList.Count - 1; num >= 0; num--)
		{
			if (orbList[num] != null)
			{
				orbList[num].QueueBurst(2.5f, burstDelay, givenStatus, emitHitEffect);
			}
			if (givenStatus)
			{
				orbList.RemoveAt(num);
			}
		}
	}
	public void ResetAllMinions()
	{
		foreach (OrbMetalFamiliar orb in orbList)
		{
			if (!(orb == null))
			{
				orb.health.healthStat.CurrentValue = -1f;
				orb.fsm.ChangeState("Dead");
			}
		}
	}
}
public class LightningBossSkyJavelinState : BossSkillState
{

		bossDisplayName = TextManager.GetUIText("enemyName-minibossRogue");
		base.Awake();
	}
	public override void InitComponents()
	{
		base.InitComponents();
		attack = transform.Find("EnemyAttackBox").GetComponent<Attack>();
	}
	public override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		attackSkillID = "SuperRogueAttack";
		fsm.AddState(new IdleState("Idle", fsm, this));
		fsm.AddState(new GoBackState("GoBack", fsm, this));
		fsm.AddState(new ChaseState("Chase", fsm, this));
		fsm.AddState(attackState = new SuperRogueAttackState("Attack", fsm, this));
		fsm.AddState(stealthState = new SuperRogueStealthState("Stealth", fsm, this, 0, 5, 0f, alertRadius, 10f));
		fsm.AddState(teleportState = new SuperRogueTeleportState("Teleport", fsm, this, 1, 9, 4f, alertRadius, 12f, newAuto: false));
		fsm.AddState(new SuperRogueShurikenState("SuperRogueShuriken", fsm, this, 1, 7, 0f, alertRadius, 0f, newAuto: false));
		fsm.AddState(regenState = new MiniBossRegenState("Regen", fsm, this, 2, 3, 0f, 30f, 20f, newAuto: false)
		{
			castingAnimName = "Crouch"
		});
		if (isFinalRoom)
		{
			fsm.AddState(new MiniBossLaserSummonState(fsm, this, "Crouch"));
		}
		fsm.AddState(new MiniBossReadyState("Ready", fsm, this)
		{
			animName = "Ready"
		});
		fsm.AddState(new SuperRogueHurtState("Hurt", fsm, this));
		fsm.AddState(new SuperRogueDeadState("Dead", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}
	public override void InitAudio()
	{
		base.InitAudio();
		attackAnimAudioPlayTime = 0.5f;
		attackAudioID = "RogueAttack";
		minPitch = 0.85f;
		maxPitch = 0.95f;
	}
	public override void AllowHurtState(bool status, bool skipBreakEffect = false, bool skipOutline = false)
	{
		if (IsStealthed)
		{
			base.AllowHurtState(status: true, skipBreakEffect: true, skipOutline: true);
		}
		else
		{
			base.AllowHurtState(status, skipBreakEffect, skipOutline);
		}
	}
	public override void SetOutlineColor(bool status)
	{
		if (IsStealthed)
		{
			if (spriteRenderer != null)
			{
				SetOutlineColor(stealthState.stealthColor, Color.clear);
			}
		}
		else
		{
			base.SetOutlineColor(status);
		}
	}
	public Rogue SummonClone(Vector2 givenPosition, string givenStateName = "")
	{
		cloneList.RemoveNullValues();
		Rogue rogue;
		if (cloneList.Count < maxCloneCount)
		{
			rogue = (Rogue)Enemy.Spawn(EName.Rogue, givenPosition, transform.parent, dropLoot: false, alerted: true, spawnCard: false, survivalMode: true, overrideCountDeath: true);
			rogue.health.healthStat.AddMod(cloneHealthMod);
			rogue.summoned = true;
			rogue.closestTargetInfo = closestTargetInfo;
			cloneList.Add(rogue);
		}
		else
		{
			rogue = cloneList[0];
			cloneList.Remove(rogue);
			cloneList.Add(rogue);
			Enemy.PlayTeleportSmokeEffect(rogue.transform.position);
			rogue.transform.position = givenPosition;
		}
		Enemy.SpawnEnemyPortal(givenPosition);
		if (givenStateName != string.Empty)
		{
			if (givenStateName == "Lunge" && rogue.stealthState != null && rogue.IsStealthed)
			{
				rogue.stealthState.EndStealth();
			}
			rogue.fsm.QueueChangeState(givenStateName);
		}
		return rogue;
	}
	public void DestroyClones()
	{
		foreach (Rogue clone in cloneList)
		{
			clone.stealthState.prevFlashColor = Color.white;
			clone.stealthState.prevFlashAmount = 0f;
			clone.stealthState.ignoreFlashAlteringStates = true;
			clone.stealthState.EndStealth();
			clone.fsm.QueueChangeState("Dead");
		}
	}
}

